n32345.content:
\begin{definition}[model parameters]
  \label{def:Params}
  \lean{ConNF.Params}
  \leanok
  A collection of \emph{model parameters} is a tuple \( (\lambda, {<_\lambda}, \kappa, \mu) \) such that
  \begin{itemize}
    \item \( {<} = {<_\lambda} \) is a well-order on \( \lambda \), and under this ordering, \( \lambda \) has no maximal element (so \( \operatorname{\mathsf{ot}}(\lambda) \) is a limit ordinal);
    \item \( \#\kappa \) is uncountable and regular;
    \item \( \#\mu \) is a strong limit, and satisfies
    \[ \#\kappa < \#\mu;\quad \#\kappa \leq \operatorname{\mathsf{cof}}(\operatorname{\mathsf{ord}}(\#\mu));\quad \operatorname{\mathsf{ot}}(\lambda) \leq \operatorname{\mathsf{ord}}(\operatorname{\mathsf{cof}}(\operatorname{\mathsf{ord}}(\#\mu))) \]
    so in particular, \( \operatorname{\mathsf{ot}}(\lambda) \leq \operatorname{\mathsf{ord}}(\#\mu) \).
    Note that the inequalities in \( \kappa \) are inequalities of cardinals; the inequality in \( \lambda \) is an inequality of ordinals.
  \end{itemize}
  Given a collection of model parameters, we define
  \begin{itemize}
    \item canonical well-orders on \( \kappa \) and \( \mu \) such that \( \operatorname{\mathsf{ot}}(\kappa) = \operatorname{\mathsf{ord}}(\#\kappa) \) and \( \operatorname{\mathsf{ot}}(\mu) = \operatorname{\mathsf{ord}}(\#\mu) \); and
    \item a canonical left-cancellative additive monoid on \( \kappa \), obtained by passing through the equivalence \( \kappa \simeq \{ o : \mathsf{Ord}\mid o < \operatorname{\mathsf{ord}}(\#\kappa) \} \).
  \end{itemize}
\end{definition}

n32346.content:
\begin{proposition}
  \uses{def:Params}
  \label{prop:Params.minimal}
  \lean{ConNF.minimalParams,ConNF.inaccessibleParams}
  \leanok
  The tuple \( (\mathbb N, {<_{\mathbb N}}, \aleph_1, \beth_{\omega_1}) \) is a collection of model parameters, where the symbols \( \aleph_1 \) and \( \beth_{\omega_1} \) represent particular types of that cardinality.
\end{proposition}

n32348.content:
\begin{definition}[type index]
  \label{def:TypeIndex}
  \uses{def:Params}
  \lean{ConNF.TypeIndex}
  \leanok
  The type of \emph{type indices} is \( \lambda^\bot \coloneq \texttt{WithBot}(\lambda) \): the collection of \emph{proper type indices} \( \lambda \) together with a designated symbol \( \bot \) which is smaller than all proper type indices.
  Note that \( \operatorname{\mathsf{ot}}(\lambda^\bot) = \operatorname{\mathsf{ot}}(\lambda) \), and hence that for each \( \alpha : \lambda^\bot \),
  \[ \#\{ \beta : \lambda^\bot \mid \beta < \alpha \} \leq \#\{ \beta : \lambda^\bot \mid \beta \leq \alpha \} < \operatorname{\mathsf{cof}}(\operatorname{\mathsf{ord}}(\#\mu)) \]
\end{definition}

n32349.content:
\begin{definition}[small]
  \label{def:Small}
  \uses{def:Params}
  \lean{ConNF.Small}
  \leanok
  A set \( s : \operatorname{\mathsf{Set}}(\tau) \) is called \emph{small} if \( \#s < \#\kappa \).
  Smallness is stable under subset, intersection, small-indexed unions, symmetric difference, direct image, injective preimage, and many other operations (each of which should be its own lemma when formalised).
  Sets \( s, t : \operatorname{\mathsf{Set}}(\tau) \) are called \emph{near} if \( s \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}t \) is small; in this case, we write \( s \mathrel{\overset{N}{\sim}}t \).
  Nearness is an equivalence relation.
  If \( s \mathrel{\overset{N}{\sim}}t \) and \( u \) is small, then \( s \mathrel{\overset{N}{\sim}}(t \mathbin{\diamond} u) \), where \( \diamond \) is one of \( \cup, \cap, \setminus, \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\).
\end{definition}

n32350.content:
\begin{definition}[litter]
  \label{def:Litter}
  \uses{def:Params}
  \lean{ConNF.Litter}
  \leanok
  A \emph{litter} is a triple \( L = (\nu, \beta, \gamma) : \mu \times \lambda^\bot \times \lambda \) where \( \beta \neq \gamma \).
  The type of all litters is denoted \( {\mathcal L}\), and \( \#{\mathcal L}= \#\mu \).
\end{definition}

n32351.content:
\begin{definition}[atom]
  \label{def:Atom}
  \uses{def:Litter}
  \lean{ConNF.Atom}
  \leanok
  An \emph{atom} is a pair \( a = (L, i) : {\mathcal L}\times \kappa \).\footnote{This should be formalised as a structure, not as a definition. We should not use the projections of atoms unless absolutely necessary.}
  The type of all atoms is denoted \( {\mathcal A}\), and \( \#{\mathcal A}= \#\mu \).
  We write \( (-)^\circ : {\mathcal A}\to {\mathcal L}\) for the operation \( (L, i) \mapsto L \).\footnote{This must be a notation typeclass.}
  We write \( \operatorname{\mathsf{LS}}(L) \coloneq \{ a \mid a^\circ = L \} \) for the \emph{litter set} of \( L \).\footnote{Maybe revise this name?}
\end{definition}

n32352.content:
\begin{definition}[near-litter]
  \label{def:NearLitter}
  \uses{def:Litter,def:Atom}
  \lean{ConNF.NearLitter}
  \leanok
  A \emph{near-litter} is a pair \( N = (L, s) : {\mathcal L}\times \operatorname{\mathsf{Set}}{\mathcal A}\) such that \( s \mathrel{\overset{N}{\sim}}\operatorname{\mathsf{LS}}(L) \).\footnote{Like with atoms, this should be a structure. We should create an actual constructor, rather than using the \( \langle - \rangle \) syntax.}
  We write \( (-)^\circ : {\mathcal N}\to {\mathcal L}\) for the operation \( (L, s) \mapsto L \).
  We write \( a \in N \) for \( a \in s \), where \( N = (L, s) \).
  Near-litters satisfy extensionality: there is at most one choice of \( L \) for each \( s \).
  Each near-litter has size \( \#\kappa \) when treated as a set of atoms.
  The type of all near-litters is denoted \( {\mathcal N}\), and \( \#{\mathcal N}= \#\mu \) (there are \( \#\mu \) litters, and \( \#\mu \) small sets of atoms by \cref{prop:card_subset_card_lt_cof}; the latter observation should be its own lemma).

  We have \( M \mathrel{\overset{N}{\sim}}N \) if and only if \( M^\circ = N^\circ \).
  If \( M^\circ = N^\circ \), then \( M \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}N \) is small and \( M \cap N \) has size \( \#\kappa \).
  If \( M^\circ \neq N^\circ \), then \( M \cap N \) has size \( \#\kappa \) and \( M \cap N \) is small.
\end{definition}

n32353.content:
\begin{definition}[base permutation]
  \label{def:BasePerm}
  \uses{def:Atom,def:Litter,def:NearLitter}
  \lean{ConNF.BasePerm}
  \leanok
  A \emph{base permutation} is a pair \( \pi = (\pi^{\mathcal A}, \pi^{\mathcal L}) \), where \( \pi^{\mathcal A}\) is a permutation \( {\mathcal A}\simeq {\mathcal A}\) and \( \pi^{\mathcal L}\) is a permutation \( {\mathcal L}\simeq {\mathcal L}\), such that
  \[ \pi^{\mathcal A}[\operatorname{\mathsf{LS}}(L)] \mathrel{\overset{N}{\sim}}\operatorname{\mathsf{LS}}(\pi^{\mathcal L}(L)) \]
  Base permutations have a natural group structure, they act on atoms by \( \pi^{\mathcal A}\), they act on litters by \( \pi^{\mathcal L}\), and they act on near-litters by\footnote{We need to emphasise these properties, rather than emphasising the real definition \( \pi(N) = (\pi(N^\circ), \pi[N]) \).}
  \[ \pi(N)^\circ = \pi(N^\circ);\quad a \in \pi(N) \leftrightarrow a \in \pi[N] \]
  Base permutations are determined by their action on atoms.
  We should avoid directly referencing \( \pi^{\mathcal A}\) and \( \pi^{\mathcal L}\) whenever possible.
\end{definition}

n32354.content:
\begin{definition}[path]
  \label{def:Path}
  \uses{def:TypeIndex}
  \lean{ConNF.Path}
  \leanok
  If \( \alpha, \beta \) are type indices, then a \emph{path} \( \alpha \rightsquigarrow\beta \) is given by the constructors
  \begin{itemize}
    \item \( \operatorname{\mathsf{nil}} : \alpha \rightsquigarrow\alpha \);
    \item \( \operatorname{\mathsf{cons}} : (\alpha \rightsquigarrow\beta) \to (\gamma < \beta) \to (\alpha \rightsquigarrow\gamma) \).
  \end{itemize}
  We define by recursion a \( \operatorname{\mathsf{snoc}} \) operation on the top of paths.
  We also prove the induction principle for \( \operatorname{\mathsf{nil}} \) and \( \operatorname{\mathsf{snoc}} \).

  A path \( \alpha \rightsquigarrow\bot \) is called an \emph{\( \alpha \)-extended index}.
  We write \( \operatorname{\mathsf{nil}}(\alpha) \) for the path \( \{ \alpha \} : \alpha \rightsquigarrow\alpha \).
  If \( h \) is a proof of \( \beta < \alpha \), we write \( \operatorname{\mathsf{single}}(h) \) for the path \( \{ \alpha, \beta \} : \alpha \rightsquigarrow\beta \).

  We have the inequality
  \begin{align*}
    \#(\alpha \rightsquigarrow\beta)
    &\leq (\#\{ \gamma : \lambda^\bot \mid \gamma \leq \alpha \})^{<\omega} \\
    &= \max(\aleph_0, \#\{ \gamma : \lambda^\bot \mid \gamma \leq \alpha \}) \\
    &< \operatorname{\mathsf{cof}}(\operatorname{\mathsf{ord}}(\#\mu))
  \end{align*}
\end{definition}

n32356.content:
\begin{definition}[structural permutation]
  \label{def:StrPerm}
  \uses{def:BasePerm,def:Tree}
  \lean{ConNF.StrPerm}
  \leanok
  Let \( \alpha \) be a type index.
  Then an \emph{\( \alpha \)-structural permutation} (or just \emph{\( \alpha \)-permutation}) is an \( \alpha \)-tree of base permutations.
  The type of \( \alpha \)-permutations is written \( \mathsf{StrPerm}_\alpha \).
\end{definition}

n32358.content:
\begin{definition}[base support]
  \label{def:BaseSupport}
  \uses{def:Enumeration,def:NearLitter}
  \lean{ConNF.BaseSupport}
  \leanok
  A \emph{base support} is a pair \( S = (S^{\mathcal A}, S^{\mathcal N}) \) where \( S^{\mathcal A}\) is an enumeration of atoms and \( S^{\mathcal N}\) is an enumeration of near-litters.
  There are precisely \( \#\mu \) base supports.
\end{definition}

n32360.content:
\begin{definition}[structural set]
  \label{def:StrSet}
  \uses{def:StrPerm}
  \lean{ConNF.StrSet}
  \leanok
  The type of \emph{\( \alpha \)-structural sets}, denoted \( \mathsf{StrSet}_\alpha \), is defined by well-founded recursion on \( \lambda^\bot \).
  \begin{itemize}
    \item \( \mathsf{StrSet}_\bot \coloneq {\mathcal A}\);
    \item \( \mathsf{StrSet}_\alpha \coloneq \prod_{\beta : \lambda^\bot} \beta < \alpha \to \operatorname{\mathsf{Set}}\mathsf{StrSet}_\beta \) where \( \alpha : \lambda \).
  \end{itemize}
  These equalities will in fact only be equivalences in the formalisation.
  We define the action of \( \alpha \)-permutations (more precisely, inhabitants of some type with a \( \texttt{StrPermClass}_\alpha \) instance) on \( \alpha \)-structural sets by well-founded recursion.
  \begin{itemize}
    \item \( \pi(x) = \pi_{\operatorname{\mathsf{nil}}(\bot)}(x) \) if \( \alpha \equiv \bot \);
    \item \( \pi(x) = (\beta, h \mapsto \pi_h[x(\beta, h)]) \) if \( \alpha : \lambda \).
  \end{itemize}
\end{definition}

n32361.content:
\begin{definition}[position function]
  \label{def:Position}
  \uses{def:Params}
  \lean{ConNF.Position}
  \leanok
  Let \( \tau \) be a type.
  A \emph{position function} for \( \tau \) is an injection \( \iota : \tau \to \mu \).
  This is a typeclass.
\end{definition}

n32362.content:
\begin{proposition}[injective functions from denied sets]
  \label{prop:funOfDeny}
  \uses{def:Params}
  \lean{ConNF.funOfDeny}
  \leanok
  Let \( \tau \) be a type such that \( \#\tau \leq \#\mu \).
  Let \( D : \tau \to \operatorname{\mathsf{Set}}(\mu) \) be a function such that for each \( x : \tau \), the set \( D(x) \), called the \emph{denied set} of \( x \), has size less than \( \operatorname{\mathsf{cof}}(\operatorname{\mathsf{ord}}(\#\mu)) \).
  Then there is an injective function \( f : \tau \to \mu \) such that if \( \nu \in D(x) \), then \( \nu < f(x) \).
\end{proposition}

n32364.content:
\begin{proposition}[base positions]
  \label{prop:BasePositions}
  \uses{def:Position}
  \leanok
  There are position functions on \( {\mathcal A}, {\mathcal N}\) that are jointly injective and satisfy
  \begin{itemize}
    \item \( \iota(\operatorname{\mathsf{NL}}(a^\circ)) < \iota(a) \) for every atom \( a \);
    \item \( \iota(\operatorname{\mathsf{NL}}(N^\circ)) \leq \iota(N) \) for every near-litter \( N \);
    \item \( \iota(a) < \iota(N) \) for every near-litter \( N \) and atom \( a \in N \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N^\circ) \).\footnote{TODO: Make syntax for \( N \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N^\circ) \).}
  \end{itemize}
  We register these position functions as instances for use in typeclass inference.
  We also define \( \iota(L) = \iota(\operatorname{\mathsf{NL}}(L)) \) for litters.
\end{proposition}

n32365.content:
\begin{proof}
  \uses{prop:funOfDeny}
  \leanok
  First, establish an equivalence \( f_{\mathcal L}: {\mathcal L}\simeq \mu \).
  Use \cref{prop:funOfDeny} to obtain an injective map \( f_{\mathcal A}: {\mathcal N}\to \mu \) such that \( f_{\mathcal L}(a^\circ) < f_{\mathcal A}(a) \) for each atom \( a \).
  Now use \cref{prop:funOfDeny} again to obtain an injective map \( f_{\mathcal N}: {\mathcal N}\to \mu \) such that
  \[ f_{\mathcal L}(N^\circ) < f_{\mathcal N}(N);\quad f_{\mathcal A}(a) < f_{\mathcal N}(N) \text{ for } a \in N \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N^\circ) \]
  Endow \( 3 \times \mu \) with its lexicographic order, of order type \( \operatorname{\mathsf{ord}}(\#\mu) \), giving an order isomorphism \( e : 3 \times \mu \simeq \mu \).
  Finally, we define
  \[ \iota(a) = e(1, f_{\mathcal A}(a));\quad \iota(N) = \begin{cases}
    e(0, f_{\mathcal L}(N^\circ)) & \text{if } N = \operatorname{\mathsf{NL}}(N^\circ) \\
    e(2, f_{\mathcal N}(N)) & \text{otherwise}
  \end{cases} \]
\end{proof}

n32366.content:
\begin{definition}[model data]
  \label{def:ModelData}
  \uses{def:StrSupport,def:StrSet}
  \lean{ConNF.ModelData}
  \leanok
  Let \( \alpha \) be a type index.
  \emph{Model data} at type \( \alpha \) consists of:\footnote{A type theory problem with \texttt{export}ing this data is that under different assumptions, things like different spellings of \( \mathsf{TSet}_\alpha \) might require case splitting on \( \alpha \) before they become defeq (e.g.\ see the old version of \texttt{Model/FOA.lean}). There doesn't seem to be an easy way around this.}
  \begin{itemize}
    \item a \( \mathsf{TSet}_\alpha \) called the type of \emph{tangled sets} or \emph{t-sets}, which will be our type of model elements at level \( \alpha \), with an embedding \( U_\alpha : \mathsf{TSet}_\alpha \to \mathsf{StrSet}_\alpha \);
    \item a group \( \mathsf{AllPerm}_\alpha \) called the type of \emph{allowable permutations}, with a \( \texttt{StrPermClass}_\alpha \) instance and a specified action on \( \mathsf{TSet}_\alpha \),
  \end{itemize}
  such that
  \begin{itemize}
    \item if \( \rho : \mathsf{AllPerm}_\alpha \) and \( x : \mathsf{TSet}_\alpha \), then \( \rho(U_\alpha(x)) = U_\alpha(\rho(x)) \);
    \item every t-set of type \( \alpha \) has an \( \alpha \)-support (\cref{def:StrSupport}) for its action under the \( \alpha \)-allowable permutations.
  \end{itemize}
\end{definition}

n32367.content:
\begin{definition}[tangle]
  \label{def:Tangle}
  \uses{def:ModelData}
  \lean{ConNF.Tangle}
  \leanok
  Let \( \alpha \) be a type index with model data.
  An \emph{\( \alpha \)-tangle} is a pair \( t = (x, S) \) where \( x \) is a tangled set of type \( \alpha \) and \( S \) is an \( \alpha \)-support for \( x \).
  We define \( \operatorname{\mathsf{set}}(t) = x \) and \( \operatorname{\mathsf{supp}}(t) = S \).
  The type of \( \alpha \)-tangles is denoted \( \mathsf{Tang}_\alpha \).
  Allowable permutations \( \rho \) act on tangles by \( \rho((x, S)) = (\rho(x), \rho(S)) \), and so \( \operatorname{\mathsf{supp}}(t) \) supports \( t \) for its action under the allowable permutations.
  Therefore, each tangled set \( x \) is of the form \( \operatorname{\mathsf{set}}(t) \) for some tangle \( t \).
\end{definition}

n32368.content:
\begin{proposition}[fuzz maps]
  \label{prop:fuzz}
  \uses{def:Tangle,def:Position}
  \lean{ConNF.fuzz}
  \leanok
  Let \( \beta \) be a type index with model data, and suppose that \( \mathsf{Tang}_\beta \) has a position function.
  Let \( \gamma \) be any proper type index not equal to \( \beta \).
  Then there is an injective \emph{fuzz map} \( f_{\beta,\gamma} : \mathsf{Tang}_\beta \to {\mathcal L}\) such that \( \iota(t) < \iota(f_{\beta,\gamma}(t)) \), and the different \( f_{\beta,\gamma} \) all have disjoint ranges.
  In particular,

n32369.content:
\begin{proof}
  \uses{prop:funOfDeny}
  \leanok
  We define \( g : \mathsf{Tang}_\beta \to \mu \) by \cref{prop:funOfDeny}, where the denied sets are given by \( D(t) = \{ \iota(t) \} \).
  Then we set \( f_{\beta,\gamma}(t) = (g(t), \beta, \gamma) \).
\end{proof}

n32370.content:
\begin{definition}[inflexible path]
  \label{def:InflexiblePath}
  \uses{prop:fuzz}
  \lean{ConNF.InflexiblePath}
  \leanok
  Let \( \alpha \) be a proper type index.
  Suppose that we have model data for all type indices \( \beta \leq \alpha \) and position functions for \( \mathsf{Tang}_\beta \) for all \( \beta < \alpha \).
  For any type index \( \beta \leq \alpha \), a \emph{inflexible \( \beta \)-path} is a tuple \( I = (\gamma, \delta, \varepsilon, A) \) where \( \delta, \varepsilon < \gamma \) are distinct, the index \( \varepsilon \) is proper, and \( A : \beta \rightsquigarrow\gamma \).
  We will write \( \gamma_I, \delta_I, \varepsilon_I, A_I \) for its fields.
  Inflexible paths have a coderivative operation, given by \( (\gamma, \delta, \varepsilon, A)^B = (\gamma, \delta, \varepsilon, A^B) \).
\end{definition}

n32371.content:
\begin{definition}[typed near-litter]
  \label{def:TypedNearLitter}
  \uses{def:ModelData,def:Tangle,prop:BasePositions}
  \lean{ConNF.TypedNearLitters}
  \leanok
  Let \( \alpha \) be a proper type index with model data, and suppose that \( \mathsf{Tang}_\alpha \) has a position function.
  We say that \( \alpha \) has \emph{typed near-litters} if there is an embedding \( \operatorname{\mathsf{typed}}_\alpha : {\mathcal N}\to \mathsf{TSet}_\alpha \) such that
  \begin{itemize}
    \item if \( \rho : \mathsf{AllPerm}_\alpha \) and \( N : {\mathcal N}\), then \( \rho(\operatorname{\mathsf{typed}}_\alpha(N)) = \operatorname{\mathsf{typed}}_\alpha(\rho_\bot(N)) \); and
    \item if \( N \) is a near-litter and \( t \) is an \( \alpha \)-tangle such that \( \operatorname{\mathsf{set}}(t) = \operatorname{\mathsf{typed}}_\alpha(N) \), we have \( \iota(N) \leq \iota(t) \).
  \end{itemize}
  Objects of the form \( \operatorname{\mathsf{typed}}_\alpha \) are called \emph{typed near-litters}.
\end{definition}

n32373.content:
\begin{definition}[code]
  \label{def:Code}
  \uses{def:ModelData}
  A \emph{code} is a pair \( c = (\beta, s) \) where \( \beta < \alpha \) is a type index and \( s \) is a nonempty set of \( \mathsf{TSet}_\beta \).
\end{definition}

n32374.content:
\begin{definition}[cloud]
  \label{def:cloud}
  \uses{def:ModelData,def:TypedNearLitter,prop:fuzz,def:Code}
  The \emph{cloud relation} \( \prec \) on codes is given by the constructor
  \[ (\beta, s) \prec (\gamma, \{ \operatorname{\mathsf{typed}}_\gamma(N) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge N^\circ = f_{\beta,\gamma}(t) \}) \]
  where \( \beta, \gamma < \alpha \) are distinct and \( \gamma \) is proper.
\end{definition}

n32375.content:
\begin{proposition}
  \label{prop:eq_of_cloud}
  \uses{def:cloud}
  If \( c \prec (\gamma, s_1) \) and \( c \prec (\gamma, s_2) \), then \( s_1 = s_2 \).
\end{proposition}

n32376.content:
\begin{proof}
  Let \( c = (\beta, s) \).
  We obtain
  \[ s_1 = \{ \operatorname{\mathsf{typed}}_\gamma(N) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge N^\circ = f_{\beta,\gamma}(t) \} = s_2 \]
  as required.
\end{proof}

n32377.content:
\begin{proposition}
  \label{prop:cloud_injective}
  \uses{def:cloud}
  The cloud relation is injective (\cref{def:relation_props}).
  That is, if \( c_1, c_2 \prec d \), then \( c_1 = c_2 \).
\end{proposition}

n32381.content:
\begin{proposition}
  \label{prop:odd_iff_not_even}
  \uses{def:cloud} % for layout convenience
  Let \( \prec \) be a relation on a type \( \tau \).
  We say that an object \( x : \tau \) is \emph{\( \prec \)-even} if all of its \( \prec \)-predecessors are odd; we say that \( x \) is \emph{\( \prec \)-odd} if it has a \( \prec \)-predecessor that is even.
  Then:
  \begin{enumerate}
    \item Minimal objects are even.
    \item If \( \prec \) is well-founded, then every object \( x : \tau \) is either even or odd, but not both.
  \end{enumerate}
\end{proposition}

n32382.content:
\begin{proof}
  \emph{Part 1.}
  Direct from the definition.

  \emph{Part 2.}
  We show this by induction along \( \prec \).
  Suppose that all \( \prec \)-predecessors of \( x \) are either even or odd but not both.
  If all of these \( \prec \)-predecessors are odd, then \( x \) is even, and it is clearly not odd, because no \( y \prec x \) is even.
  Otherwise, there is \( y \prec x \) that is even, so \( x \) is odd, and it is not even because this \( y \) is not odd.
\end{proof}

n32383.content:
\begin{definition}
  \uses{def:cloud}
  \label{def:Code.Represents}
  We define the relation \( \looparrowright \) between codes by the following two constructors.
  \begin{itemize}
    \item If \( c \) is a \( \prec \)-even code, then \( c \looparrowright c \).
    \item If \( c \) is a \( \prec \)-even code and \( c \prec d \), then \( c \looparrowright d \).
  \end{itemize}
  This relation is cofunctional (\cref{def:relation_props}): if \( d \) is a code, there is exactly one \( c \) such that \( c \looparrowright d \).
  Moreover, if \( c \looparrowright (\beta, s_1), (\beta, s_2) \), then \( s_1 = s_2 \).
\end{definition}

n32387.content:
\begin{definition}[new allowable permutation]
  \label{def:NewAllPerm}
  \uses{prop:fuzz}
  A \emph{new allowable permutation} is a dependent function \( \rho \) of type \( \prod_{\beta < \alpha} \mathsf{AllPerm}_\beta \), subject to the condition
  \[ (\rho_\gamma)_\bot(f_{\beta,\gamma}(t)) = f_{\beta,\gamma}(\rho(\beta)(t)) \]
  for every \( t : \mathsf{Tang}_\beta \).
  These form a group and have a \( \texttt{StrPermClass}_\alpha \) instance.
\end{definition}

n32388.content:
\begin{proposition}
  \label{prop:AllPerm.smul_cloud_smul}
  \uses{def:NewAllPerm,def:Code.Represents,prop:Code.ext}
  Define an action of allowable permutations on codes by
  \[ \rho(\beta, s) = (\beta, \rho(\beta)[s]) \]
  Then
  \begin{enumerate}
    \item \( c \prec d \) implies \( \rho(c) \prec \rho(d) \);
    \item \( c \looparrowright d \) implies \( \rho(c) \looparrowright \rho(d) \);
    \item \( c \) is even if and only if \( \rho(c) \) is even;
    \item \( x \in_\beta c \) if and only if \( \rho(\beta)(x) \in_\beta \rho(c) \).
  \end{enumerate}
\end{proposition}

n32389.content:
\begin{proof}
  \emph{Part 1.}
  Suppose that \( c \prec d \).
  Then, writing \( c = (\beta, s) \) and \( d = (\gamma, s') \), we obtain
  \[ s' = \{ \operatorname{\mathsf{typed}}_\gamma(N) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge N^\circ = f_{\beta,\gamma}(t) \} \]
  Now, note that
  \begin{align*}
    \rho(\gamma)[s']
    &= \rho(\gamma)[\{ \operatorname{\mathsf{typed}}_\gamma(N) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge N^\circ = f_{\beta,\gamma}(t) \}] \\
    &= \{ \rho(\gamma)(\operatorname{\mathsf{typed}}_\gamma(N)) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge N^\circ = f_{\beta,\gamma}(t) \} \\
    &= \{ \operatorname{\mathsf{typed}}_\gamma(\rho(\gamma)_\bot(N)) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge N^\circ = f_{\beta,\gamma}(t) \} \\
    &= \{ \operatorname{\mathsf{typed}}_\gamma(N) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge \rho(\gamma)_\bot^{-1}(N)^\circ = f_{\beta,\gamma}(t) \} \\
    &= \{ \operatorname{\mathsf{typed}}_\gamma(N) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge N^\circ = \rho(\gamma)_\bot(f_{\beta,\gamma}(t)) \} \\
    &= \{ \operatorname{\mathsf{typed}}_\gamma(N) \mid \exists t : \mathsf{Tang}_\beta,\, \operatorname{\mathsf{set}}(t) \in s \wedge N^\circ = f_{\beta,\gamma}(\rho(\beta)(t)) \}
  \end{align*}
  So \( \rho(c) \prec \rho(d) \) as required.

  \emph{Part 2.}
  Direct.

  \emph{Part 3.}
  Follows from the general fact that if \( f : \tau \to \sigma \) is a bijection and we have \( x \prec_\tau y \) if and only if \( f(x) \prec_\sigma f(y) \), then the \( \prec_\tau \)-parity of \( x \) is the same as the \( \prec_\sigma \)-parity of \( f(x) \).

  \emph{Part 4.}
  We only need to show one direction, because we can apply the one-directional result to \( \rho^{-1} \) to obtain the converse.
  Suppose that \( x \in_\beta c \), so \( c \looparrowright (\beta, s) \) and \( x \in s \).
  Then \( \rho(c) \looparrowright (\beta, \rho(\beta)[s]) \), so \( \rho(\beta)(x) \in_\beta \rho(c) \) as required,
\end{proof}

n32390.content:
\begin{definition}[new t-set]
  \label{def:NewTSet}
  \uses{prop:AllPerm.smul_cloud_smul}
  A \emph{new t-set} is an even code \( c \) such that there is an \( \alpha \)-support that supports \( c \) under the action of new allowable permutations, or a designated object called the empty set.
  New allowable permutations act on new t-sets in the same way that they act on codes, and map the empty set to itself.
  We define the map \( U_\alpha \) from new t-sets to \( \mathsf{StrSet}_\alpha \) by cases from the top of the path in the obvious way (using recursion on paths and the membership relation from \cref{prop:Code.ext}).
  It is easy to check that \( \rho(U_\alpha(x)) = U_\alpha(\rho(x)) \) by \cref{prop:AllPerm.smul_cloud_smul}.
\end{definition}

n32391.content:
\begin{definition}[new model data]
  \uses{def:NewAllPerm,def:NewTSet,prop:Code.ext}
  \label{def:NewModelData}
  Given model data, position functions, and typed near-litters for all types \( \beta < \alpha \), \emph{new model data} is the model data at level \( \alpha \) consisting of new t-sets (\cref{def:NewTSet}) and new allowable permutations (\cref{def:NewAllPerm}).
  The embedding from new t-sets to \( \mathsf{StrSet}_\alpha \) is defined by
  \[ U_\alpha(c)(\beta) = \{ x \mid x \in_\beta c \} \]
\end{definition}

n32392.content:
\begin{definition}[typed near-litters]
  \uses{def:NewTSet}
  \label{def:newTypedNearLitter}
  We define a function \( \operatorname{\mathsf{typed}}_\alpha \) from the type of near-litters to the type of new t-sets by mapping a near-litter \( N \) to the code \( (\bot, N) \).
  This code is even as all codes of the form \( (\bot, s) \) are even.
  This function is clearly injective, and satisfies
  \[ \rho(\operatorname{\mathsf{typed}}_\alpha(N)) = \operatorname{\mathsf{typed}}_\alpha(\rho(\bot)(N)) \]
  by definition.
\end{definition}

n32393.content:
\begin{definition}[singletons]
  \uses{def:NewTSet}
  \label{def:newSingleton}
  We define a function \( \operatorname{\mathsf{singleton}}_\alpha \) for each lower type index \( \beta \) from \( \mathsf{TSet}_\beta \) to the type of new t-sets by \( x \mapsto (\beta, \{x\}) \).
  The given code is even as all singleton codes are even.
  This satisfies \( U_\alpha(\operatorname{\mathsf{singleton}}_\alpha(x))(\beta) = \{ x \} \).
\end{definition}

n32394.content:
\begin{proposition}[position function]
  \uses{def:NewModelData,def:newTypedNearLitter}
  \label{prop:newPos}
  Using the model data from \cref{def:NewModelData}, if \( \#\mathsf{Tang}_\alpha \leq \#\mu \), then there is a position function on the type of \( \alpha \)-tangles,\footnote{It may be easier in practice to construct a position function on the product of the type of new t-sets and the type of \( \alpha \)-supports, and then get the required position function on tangles from this.} such that
  \begin{itemize}
    \item if \( N \) is a near-litter and \( t \) is an \( \alpha \)-tangle such that \( \operatorname{\mathsf{set}}(t) = \operatorname{\mathsf{typed}}_\alpha(N) \), we have \( \iota(N) \leq \iota(t) \); and
    \item if \( t \) is an \( \alpha \)-tangle and \( x \) is an atom or near-litter that occurs in the range of \( \operatorname{\mathsf{supp}}(t)_A \), then \( \iota(x) < \iota(t) \).
  \end{itemize}
\end{proposition}

n32395.content:
\begin{proof}
  \uses{prop:funOfDeny}
  We use \cref{prop:funOfDeny} to construct the position function, using denied set
  \[ D(t) = \{ \iota(N) \mid \operatorname{\mathsf{set}}(t) = \operatorname{\mathsf{typed}}_\alpha(N) \} \cup \{ \iota(a) \mid a \in \operatorname{\mathsf{im}}\operatorname{\mathsf{supp}}(t)_A^{\mathcal A}\} \cup \{ \iota(N) \mid N \in \operatorname{\mathsf{im}}\operatorname{\mathsf{supp}}(t)_A^{\mathcal N}\} \]
  The first set is a subsingleton and the second two sets are small, so the denied set has size less than \( \operatorname{\mathsf{cof}}(\operatorname{\mathsf{ord}}(\#\mu)) \) as required.
\end{proof}

n32396.content:
\begin{definition}[base approximation]
  \label{def:BaseApprox}
  \uses{def:NearLitter}
  \lean{ConNF.BaseApprox}
  \leanok
  A \emph{base approximation} is a pair \( \psi = (\psi^{E{\mathcal A}}, \psi^{\mathcal L}) \) such that \( \psi^{E{\mathcal A}} \) and \( \psi^{\mathcal L}\) are permutative relations of atoms and litters respectively (\cref{def:relation_props}), and for each litter \( L \), the set
  \[ \operatorname{\mathsf{LS}}(L) \cap \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}} \]
  is small.
  The relation \( \psi^{E{\mathcal A}} \) is called the \emph{exceptional atom graph}, and \( \psi^{\mathcal L}\) is called the \emph{litter graph}.
  We make the following definitions.
  \begin{itemize}
    \item The \emph{inverse} of a base approximation is \( \psi^{-1} = ((\psi^{E{\mathcal A}})^{-1}, (\psi^{\mathcal L})^{-1}) \).
    \item If \( \psi \) and \( \chi \) are base approximations where \( \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}} = \operatorname{\mathsf{coim}}\chi^{E{\mathcal A}} \) and \( \operatorname{\mathsf{coim}}\psi^{\mathcal L}= \operatorname{\mathsf{coim}}\chi^{\mathcal L}\), then their \emph{composition} \( \psi \circ \chi \) is the base approximation \( (\psi^{E{\mathcal A}} \circ \chi^{E{\mathcal A}}, \psi^{\mathcal L}\circ \chi^{\mathcal L}) \).
    \item The \emph{\( \psi \)-sublitter} of a litter \( L \), written \( L_\psi \), is the near-litter \( (L, \operatorname{\mathsf{LS}}(L) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}) \).
  \end{itemize}
\end{definition}

n32397.content:
\begin{definition}[atom graph of an approximation]
  \uses{def:BaseApprox}
  \label{def:atomGraph}
  \lean{ConNF.BaseApprox.atoms}
  \leanok
  The \emph{typical atom graph} of \( \psi \) is the relation \( \psi^{T{\mathcal A}} \) given by the following constructor.
  If \( (L_1, L_2) \in \psi^{\mathcal L}\), then
  \[ (h_{(L_1)_\psi}(i), h_{(L_2)_\psi}(i)) \in \psi^{T{\mathcal A}} \]
  for some \( i : \kappa \), where for any near-litter \( N \), \( h_N \) is an equivalence \( \kappa \simeq N \) chosen in advance.

  The \emph{atom graph} of \( \psi \) is the relation \( \psi^{\mathcal A}= \psi^{E{\mathcal A}} \sqcup \psi^{T{\mathcal A}} \): the join of the exceptional and typical atom graphs.
\end{definition}

n32398.content:
\begin{proposition}
  \uses{def:atomGraph}
  \label{prop:atomGraph_inv}
  \lean{ConNF.BaseApprox.instInv}
  \leanok
  \( (\psi^{T{\mathcal A}})^{-1} = (\psi^{-1})^{T{\mathcal A}} \) and hence \( (\psi^{\mathcal A})^{-1} = (\psi^{-1})^{\mathcal A}\).
\end{proposition}

n32399.content:
\begin{proof}
  \leanok
  This follows directly from the fact that \( L_\psi = L_{\psi^{-1}} \) for any litter \( L \).
\end{proof}

n32400.content:
\begin{proposition}
  \uses{def:atomGraph}
  \label{prop:atomGraph_permutative}
  \lean{ConNF.BaseApprox.typical_permutative,ConNF.BaseApprox.atoms_permutative}
  \leanok
  The graphs \( \psi^{T{\mathcal A}} \) and \( \psi^{\mathcal A}\) are permutative.
\end{proposition}

n32401.content:
\begin{proof}
  \uses{prop:atomGraph_inv}
  \leanok
  The typical atom graph is injective, because the equation \( h_{L_\psi}(i)^\circ = L \) can be used to establish the the parameters of the relevant \( h \) maps coincide.
  Furthermore, we can use the fact that \( \psi^{\mathcal L}\) has equal image and coimage to produce images of any image element of this relation.
  We then appeal to symmetry using \cref{prop:atomGraph_inv} to conclude that \( \psi^{T{\mathcal A}} \) is permutative.

  The (co)image of \( \psi^{T{\mathcal A}} \) is
  \[ \bigcup_{L \in \operatorname{\mathsf{coim}}\psi^{\mathcal L}} L_\psi = \bigcup_{L \in \operatorname{\mathsf{coim}}\psi^{\mathcal L}} (\operatorname{\mathsf{LS}}(L) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}) \]
  which is clearly disjoint from the coimage of \( \psi^{E{\mathcal A}} \).\footnote{This result should of course be its own lemma.}
  So \( \psi^{\mathcal A}\) is permutative by one of the results of \cref{prop:relation_results}.
\end{proof}

n32402.content:
\begin{proposition}
  \uses{def:atomGraph}
  \label{prop:comp_atomGraph}
  If \( \psi, \chi \) have equal exceptional atom and litter coimages, then \( (\psi \circ \chi)^{T{\mathcal A}} = \psi^{T{\mathcal A}} \circ \chi^{T{\mathcal A}} \).
\end{proposition}

n32404.content:
\begin{definition}[near-litter graph of an approximation]
  \uses{def:atomGraph}
  \label{def:nearLitterGraph}
  \lean{ConNF.BaseApprox.nearLitters}
  \leanok
  The \emph{near-litter graph}

n32405.content:
\begin{proposition}
  \uses{def:nearLitterGraph}
  \label{prop:approx_near}
  \lean{ConNF.BaseApprox.image_near_of_near}
  \leanok
  Let \( s \) be a set of atoms near \( \operatorname{\mathsf{LS}}(L) \) for some litter \( L \).
  If \( (L, L') \in \psi^{\mathcal L}\), then the image of \( \psi^{\mathcal A}\) on \( s \) is near \( \operatorname{\mathsf{LS}}(L') \).
\end{proposition}

n32407.content:
\begin{proposition}
  \uses{def:nearLitterGraph}
  \label{prop:nearLitterGraph_permutative}
  \lean{ConNF.BaseApprox.inv_nearLitters,ConNF.BaseApprox.nearLitters_permutative}
  \leanok
  \( (\psi^{-1})^{\mathcal N}= (\psi^{\mathcal N})^{-1} \), and \( \psi^{\mathcal N}\) is permutative.
\end{proposition}

n32409.content:
\begin{definition}
  \uses{def:nearLitterGraph}
  \label{def:smulApproxSupport}
  Base approximations act on base supports in the following way.
  If \( S^{\mathcal A}= (i, f) \), then \( \psi(S)^{\mathcal A}= (i, f') \) where
  \[ f' = \{ (j, a_2) \mid (j, a_1) \in f \wedge (a_1, a_2) \in \psi^{\mathcal A}\} \]
  The same definition is used for near-litters.
\end{definition}

n32410.content:
\begin{definition}
  \uses{def:BaseApprox}
  \label{def:BaseApprox.LE}
  \lean{ConNF.BaseApprox.instPartialOrder}
  \leanok
  We define a partial order on base approximations by setting \( \psi \leq \chi \) when \( \psi^{E{\mathcal A}} = \chi^{E{\mathcal A}} \) and \( \psi^{\mathcal L}\leq \chi^{\mathcal L}\).
\end{definition}

n32411.content:
\begin{proposition}[adding orbits]
  \uses{def:BaseApprox.LE}
  \label{prop:BaseApprox.addOrbit}
  \lean{ConNF.BaseApprox.addOrbit}
  \leanok
  Let \( \psi \) be a base approximation, and let \( L : \mathbb N \to {\mathcal L}\) be a function such that
  \[ L(m) = L(n) \to L(m+k) = L(n+k) \]
  for all integers \( m, n, k : \mathbb Z \).
  Suppose that for all \( n \), \( L(n) \notin \operatorname{\mathsf{coim}}\psi^{\mathcal L}\).
  Then there is an extension \( \chi \geq \psi \) such that \( \chi^{\mathcal L}(L(n)) = L(n+1) \) and \( \operatorname{\mathsf{coim}}\chi^{\mathcal L}= \operatorname{\mathsf{coim}}\psi^{\mathcal L}\cup \operatorname{\mathsf{ran}}L \).
\end{proposition}

n32413.content:
\begin{definition}
  \uses{def:BaseApprox.LE,def:Tree}
  \label{def:StrApprox}
  \lean{ConNF.StrApprox}
  \leanok
  For a type index \( \beta \), a \emph{\( \beta \)-approximation} is a \( \beta \)-tree of base approximations.
  We define the partial order on \( \beta \)-approximations branchwise.
  We define an action of \( \beta \)-approximations \( \psi \) on \( \beta \)-supports \( S \) by \( (\psi(S))_A = \psi_A(S_A) \).
\end{definition}

n32414.content:
\begin{definition}
  \uses{def:InflexiblePath}
  \label{def:Inflexible}
  \lean{ConNF.Inflexible}
  \leanok
  Let \( A \) be a \( \beta \)-extended type index.
  A litter \( L \) is \emph{\( A \)-inflexible} if there is an inflexible \( \beta \)-path \( I \) such that \( A = ((A_I)_{\varepsilon_I})_\bot \) and \( L = f_{\delta_I, \varepsilon_I}(t) \) for some \( t : \mathsf{Tang}_{\delta_I} \).
  The coderivative operation works in the obvious way.
  A litter can be \( A \)-inflexible in at most one way.\footnote{We should make \( A \)-inflexibility into a subsingleton structure.}

  We say that a \( L \) is \emph{\( A \)-flexible} if it is not \( A \)-inflexible.\footnote{This is not data, but a proposition.}
  If \( L \) is \( B_A \)-flexible, then \( L \) is \( A \)-flexible.
\end{definition}

n32415.content:
\begin{definition}
  \uses{def:StrApprox,def:Inflexible,def:smulApproxSupport}
  \label{def:StrApprox.Coherent}
  \lean{ConNF.StrApprox.CoherentAt,ConNF.StrApprox.Coherent}
  \leanok
  A \( \beta \)-approximation \( \psi \) is \emph{coherent} at \( (A, L_1, L_2) \) if:
  \begin{itemize}
    \item If \( L_1 \) is \( A \)-inflexible with inflexible \( \beta \)-path \( I = (\gamma, \delta, \varepsilon, B) \) and tangle \( t : \mathsf{Tang}_\delta \), then there is some \( \delta \)-allowable permutation \( \rho \) such that
    \[ (\psi_B)_\delta(\operatorname{\mathsf{supp}}(t)) = \rho(\operatorname{\mathsf{supp}}(t)) \]
    and
    \[ L_2 = f_{\delta,\varepsilon}(\rho(t)) \]
    (and hence all \( \delta \)-allowable permutations \( \rho \) such that \( (\psi_B)_\delta(\operatorname{\mathsf{supp}}(t)) = \rho(\operatorname{\mathsf{supp}}(t)) \) satisfy \( L_2 = f_{\delta,\varepsilon}(\rho(t)) \)).
    \item If \( L_1 \) is \( A \)-flexible, then \( L_2 \) is \( A \)-flexible.
  \end{itemize}
  We say that \( \psi \) is \emph{coherent} if whenever \( (L_1, L_2) \in \psi_A^{\mathcal L}\), \( \psi \) is coherent at \( (A, L_1, L_2) \).
\end{definition}

n32416.content:
\begin{proposition}[adding orbits coherently]
  \uses{prop:BaseApprox.addOrbit,def:StrApprox.Coherent}
  \label{prop:StrApprox.addOrbit}
  \lean{ConNF.StrApprox.addOrbit_coherent}
  \leanok
  Suppose that \( \psi \) is an approximation and \( L : \mathbb Z \to {\mathcal L}\) is a function satisfying the hypotheses of \cref{prop:BaseApprox.addOrbit}.
  Let \( \chi \) be the extension produced by the structural version of this result.\footnote{We need the extension exactly as produced (as data), not an arbitrary extension satisfying the conclusion of the proposition.}
  If \( \psi \) is coherent, and is additionally coherent at \( (L(n), L(n+1)) \) for each integer \( n \), then \( \chi \) is coherent.
\end{proposition}

n32417.content:
\begin{proof}
  \leanok
  This proof just relies on the fact that if \( (\psi_B)_\delta(\operatorname{\mathsf{supp}}(t)) = \rho(\operatorname{\mathsf{supp}}(t)) \), then the same holds for every extension \( \chi \) of \( \psi \).\footnote{Maybe there's a better lemma to abstract out this idea for this and \cref{prop:StrApprox.chain}?}
\end{proof}

n32418.content:
\begin{proposition}
  \uses{def:StrApprox.Coherent}
  \label{prop:StrApprox.Coherent.inv}
  If \( \psi \) is coherent, then \( \psi^{-1} \) is coherent.
\end{proposition}

n32420.content:
\begin{proposition}
  \uses{def:StrApprox.Coherent}
  \label{prop:StrApprox.Coherent.comp}
  If \( \psi \) and \( \chi \) are coherent and have equal coimages along all paths, then \( \psi \circ \chi \) is coherent.
\end{proposition}

n32422.content:
\begin{proposition}
  \uses{def:StrApprox.Coherent}
  \label{prop:StrApprox.Coherent.deriv}
  If \( \psi \) is a coherent \( \beta \)-approximation and \( A \) is a path \( \beta \rightsquigarrow\beta' \), then \( \psi_A \) is a coherent \( \beta' \)-approximation.
\end{proposition}

n32424.content:
\begin{definition}[approximates]
  \uses{def:StrApprox,def:atomGraph,prop:atomGraph_inv,prop:comp_atomGraph,prop:nearLitterGraph_permutative}
  \label{def:StrApprox.Approximates}
  \lean{ConNF.StrApprox.Approximates}
  \leanok
  We say that a \( \beta \)-approximation \( \psi \) \emph{approximates} a \( \beta \)-allowable permutation \( \rho \) if \( \psi_A^{\mathcal L}\leq \rho_A^{\mathcal L}\) and \( \psi_A^{\mathcal A}\leq \rho_A^{\mathcal A}\) for each path \( A : \beta \rightsquigarrow\bot \).
  If \( \psi \) approximates \( \rho \) then \( \psi^n \) approximates \( \rho^n \) for each \( n : \mathbb Z \).\footnote{We should define what it means for a base approximation to approximate a near-litter permutation, and define this in terms of that.}
  A \( \beta \)-approximation \( \psi \) \emph{exactly approximates} a \( \beta \)-allowable permutation \( \rho \) if \( \psi \) approximates \( \rho \), and in addition, if \( a \) is an atom and \( A : \beta \rightsquigarrow\bot \), then \( a \notin \operatorname{\mathsf{coim}}\psi_A^{\mathcal A}\) implies \( \rho(a)^\circ = \rho(a^\circ) \) and \( \rho^{-1}(a)^\circ = \rho^{-1}(a^\circ) \).
\end{definition}

n32425.content:
\begin{definition}[freedom of action]
  \uses{def:StrApprox.Approximates}
  \label{def:FreedomOfAction}
  \lean{ConNF.StrApprox.FreedomOfAction}
  \leanok
  We say that \emph{freedom of action} holds at a type index \( \delta \) if every coherent \( \delta \)-approximation exactly approximates some \( \delta \)-allowable permutation.
\end{definition}

n32426.content:
\begin{proposition}[adding flexible litters]
  \uses{def:Inflexible,def:StrApprox}
  \label{prop:StrApprox.addFlexible}
  \lean{ConNF.StrApprox.addFlexible}
  \leanok
  Let \( \psi \) be a coherent \( \beta \)-approximation, and let \( L \) be \( A \)-flexible.
  Then there is a coherent extension \( \chi \geq \psi \) with \( L \in \operatorname{\mathsf{coim}}\chi_A^{\mathcal L}\).
\end{proposition}

n32427.content:
\begin{proof}
  \uses{prop:StrApprox.addOrbit}
  \leanok
  Define \( L' : \mathbb Z \to {\mathcal L}\) by \( L'(n) = L \), then appeal to \cref{prop:StrApprox.addOrbit} to obtain \( \chi \geq \psi \).
  All we must do is check that \( \psi \) is coherent at \( (L, L) \), which is trivial.
\end{proof}

n32428.content:
\begin{proposition}[adding inflexible litters]
  \uses{def:FreedomOfAction,def:StrApprox}
  \label{prop:StrApprox.addInflexible}
  Let \( \psi \) be a coherent \( \beta \)-approximation, and let \( L \) be \( A \)-inflexible with path \( (\gamma, \delta, \varepsilon, B) \) and tangle \( t : \mathsf{Tang}_\delta \).
  Suppose that \( (\psi_B)_\delta \) is defined on all of \( \operatorname{\mathsf{supp}}(t) \).\footnote{This is a nontrivial definition to make.}
  Suppose that freedom of action holds at level \( \delta \).
  Then there is a coherent extension \( \chi \geq \psi \) with \( L \in \operatorname{\mathsf{coim}}\chi_A^{\mathcal L}\).
\end{proposition}

n32430.content:
\begin{proposition}
  \uses{def:StrApprox.Coherent}
  \label{prop:StrApprox.chain}
  \lean{ConNF.StrApprox.exists_isMax}
  \leanok
  If \( (\psi_i)_{i : I} \) is a chain of coherent approximations where \( I \) is a linear order, then the supremum \( \psi \) is coherent.
\end{proposition}

n32431.content:
\begin{proof}
  \leanok
  Direct, using the same idea as the proof of \cref{prop:StrApprox.addOrbit}.
\end{proof}

n32432.content:
\begin{theorem}[freedom of action]
  \uses{def:FreedomOfAction}
  \label{thm:StrApprox.foa}
  \lean{ConNF.StrApprox.exists_exactlyApproximates}
  \leanok
  Freedom of action holds at all type indices \( \beta \leq \alpha \).
\end{theorem}

n32434.content:
\begin{definition}
  \uses{def:NearLitter}
  \label{def:Interference}
  \lean{ConNF.Interference}
  \leanok
  The \emph{interference} of near-litters \( N_1, N_2 \) is
  \[ \operatorname{\mathsf{interf}}(N_1, N_2) = \begin{cases}
    N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}N_2 & \text{if } N_1^\circ = N_2^\circ \\
    N_1 \cap N_2 & \text{if } N_1^\circ \neq N_2^\circ
  \end{cases} \]
  which is a small set of atoms.
\end{definition}

n32435.content:
\begin{definition}
  \uses{def:Interference,def:BaseSupport}
  \label{def:BaseAction}
  \lean{ConNF.BaseAction}
  \leanok
  A \emph{base action} is a pair \( \xi = (\xi^{\mathcal A}, \xi^{\mathcal N}) \) such that \( \xi^{\mathcal A}\) and \( \xi^{\mathcal N}\) are relations of atoms and near-litters respectively (\cref{def:relation_props}), such that
  \begin{itemize}
    \item \( \xi^{\mathcal A}\) and \( \xi^{\mathcal N}\) are defined on small sets;
    \item \( \xi^{\mathcal A}\) is one-to-one;
    \item if \( (a_1, a_2) \in \xi^{\mathcal A}\) and \( (N_1, N_2) \in \xi^{\mathcal N}\), then \( a_1 \in N_1 \) if and only if \( a_2 \in N_2 \);
    \item if \( (N_1, N_3), (N_2, N_4) \in \xi^{\mathcal N}\), then \( N_1^\circ = N_2^\circ \) if and only if \( N_3^\circ = N_4^\circ \);
    \item for each \( (N_1, N_3), (N_2, N_4) \in \xi^{\mathcal N}\),
    \[ \operatorname{\mathsf{interf}}(N_1, N_2) \subseteq \operatorname{\mathsf{coim}}\xi^{\mathcal A};\quad \operatorname{\mathsf{interf}}(N_3, N_4) \subseteq \operatorname{\mathsf{im}}\xi^{\mathcal A}\]
  \end{itemize}
  Note that these conditions imply that \( \xi^{\mathcal N}\) is one-to-one.
  We define the one-to-one relation \( \xi^{\mathcal L}\) by the constructor
  \[ (N_1, N_2) \in \xi^{\mathcal N}\to (N_1^\circ, N_2^\circ) \in \xi^{\mathcal L}\]

  The partial order on base actions is defined by \( \xi \leq \zeta \) if and only if \( \xi^{\mathcal A}\leq \zeta^{\mathcal A}\) and \( \xi^{\mathcal N}= \zeta^{\mathcal N}\).\footnote{We should make utilities for constructing extensions of base actions, reducing the proof obligations of showing that these are base actions (e.g.\ removing the last two bullet points and not needing to prove results we already know about \( \xi \)).}
  The inverse of \( \xi \) is \( ((\xi^{\mathcal A})^{-1}, (\xi^{\mathcal N})^{-1}) \).
  They act on base supports in the natural way.
\end{definition}

n32436.content:
\begin{definition}
  \uses{def:BaseAction}
  \label{def:BaseAction.Nice}
  \lean{ConNF.BaseAction.Nice}
  \leanok
  A base action \( \xi \) is \emph{nice} if whenever \( (N_1, N_2) \in \xi^{\mathcal N}\),
  \[ N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_1^\circ) \subseteq \operatorname{\mathsf{coim}}\xi^{\mathcal A};\quad N_2 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_2^\circ) \subseteq \operatorname{\mathsf{im}}\xi^{\mathcal A}\]
\end{definition}

n32437.content:
\begin{proposition}[extending orbits inside near-litters]
  \uses{def:BaseAction}
  \label{prop:BaseAction.exists_inside}
  \lean{ConNF.BaseAction.insideExtension}
  \leanok
  Every base action \( \xi \) admits an extension \( \zeta \) satisfying
  \[ \forall N \in \operatorname{\mathsf{coim}}\xi^{\mathcal N},\, N \setminus \operatorname{\mathsf{LS}}(N^\circ) \subseteq \operatorname{\mathsf{coim}}\xi^{\mathcal A}\]
\end{proposition}

n32439.content:
\begin{proposition}[extending orbits outside near-litters]
  \uses{def:BaseAction}
  \label{prop:BaseAction.exists_outside}
  \lean{ConNF.BaseAction.outsideExtension}
  \leanok
  Every base action \( \xi \) admits an extension \( \zeta \) satisfying
  \[ \forall N \in \operatorname{\mathsf{coim}}\xi^{\mathcal N},\, \operatorname{\mathsf{LS}}(N) \setminus N \subseteq \operatorname{\mathsf{coim}}\xi^{\mathcal A}\]
\end{proposition}

n32441.content:
\begin{proposition}
  \uses{def:BaseAction.Nice}
  \label{prop:BaseAction.exists_nice}
  \lean{ConNF.BaseAction.niceExtension}
  \leanok
  Every base action has a nice extension.
\end{proposition}

n32442.content:
\begin{proof}
  \leanok
  \uses{prop:BaseAction.exists_outside,prop:BaseAction.exists_inside}
  Apply \cref{prop:BaseAction.exists_inside} to \( \xi \) to obtain \( \xi_1 \); apply \cref{prop:BaseAction.exists_inside} again to \( \xi_1^{-1} \) to obtain \( \xi_2 \); apply \cref{prop:BaseAction.exists_outside} to \( \xi_2 \) to obtain \( \xi_3 \), and finally apply \cref{prop:BaseAction.exists_outside} again to \( \xi_3^{-1} \) to obtain \( \xi_4 \), our target.
\end{proof}

n32443.content:
\begin{definition}
  \uses{def:Tree,def:BaseAction,def:StrSupport}
  \label{def:StrAction}
  For a type index \( \beta \), a \emph{\( \beta \)-action} is a \( \beta \)-tree of base actions.
  We define an action of \( \beta \)-actions \( \xi \) on \( \beta \)-supports \( S \) by \( (\xi(S))_A = \xi_A(S_A) \).
\end{definition}

n32444.content:
\begin{definition}
  \uses{def:StrAction,def:Inflexible}
  \label{def:StrAction.Coherent}
  A \( \beta \)-action \( \xi \) is \emph{coherent} at \( (A, L_1, L_2) \) if:
  \begin{itemize}
    \item If \( L_1 \) is \( A \)-inflexible with inflexible \( \beta \)-path \( I = (\gamma, \delta, \varepsilon, B) \) and tangle \( t : \mathsf{Tang}_\delta \), then there is some \( \delta \)-allowable permutation \( \rho \) such that
    \[ (\xi_B)_\delta(\operatorname{\mathsf{supp}}(t)) = \rho(\operatorname{\mathsf{supp}}(t)) \]
    and
    \[ L_2 = f_{\delta,\varepsilon}(\rho(t)) \]
    (and hence again every \( \delta \)-allowable \( \rho \) satisfying the hypothesis also satisfies the conclusion).
    \item If \( L_1 \) is \( A \)-flexible, then \( L_2 \) is \( A \)-flexible.
  \end{itemize}
  We say that \( \xi \) is \emph{coherent} if whenever \( (L_1, L_2) \in \xi_A^{\mathcal L}\), \( \xi \) is coherent at \( (A, L_1, L_2) \).
\end{definition}

n32445.content:
\begin{definition}
  \uses{def:StrAction,def:StrApprox.Coherent}
  \label{def:FlexApprox}
  \lean{ConNF.BaseAction.FlexApprox}
  \leanok
  Let \( A : \beta \rightsquigarrow\bot \).
  An \emph{\( A \)-flexible approximation} of a base action \( \xi \) is a base approximation \( \psi \) such that
  \begin{enumerate}
    \item \( \xi^{\mathcal A}\leq \psi^{E{\mathcal A}} \);
    \item if \( L \in \operatorname{\mathsf{coim}}\psi^{\mathcal L}\), then \( L \) is \( A \)-flexible;
    \item if \( (N_1, N_2) \in \xi^{\mathcal N}\) and \( N_1^\circ \) is \( A \)-flexible, then \( (N_1^\circ, N_2^\circ) \in \psi^{\mathcal L}\);
    \item if \( (N_1, N_2) \in \xi^{\mathcal N}\), then \( N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_1^\circ) \subseteq \operatorname{\mathsf{coim}}\psi^{\mathcal A}\) and \( N_2 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_2^\circ) \subseteq \operatorname{\mathsf{coim}}\psi^{\mathcal A}\);
    \item if \( (N_1, N_2) \in \xi^{\mathcal N}\), then for each atom \( a_2 \),
    \[ a_2 \in N_2 \leftrightarrow (\exists a_1 \in N_1,\, (a_1, a_2) \in \psi^{E{\mathcal A}}) \vee (a_2 \notin \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}} \wedge a_2^\circ = N_2^\circ) \]
  \end{enumerate}
  A \emph{flexible approximation} of a \( \beta \)-action \( \xi \) is a \( \beta \)-approximation \( \psi \) such that for each \( A : \beta \rightsquigarrow\bot \), the base approximation \( \psi_A \) is an \( A \)-flexible approximation of \( \xi_A \).
  Flexible approximations are coherent.
\end{definition}

n32446.content:
\begin{proposition}
  \uses{def:FlexApprox}
  \label{prop:exists_flexApprox}
  \lean{ConNF.BaseAction.flexApprox_flexApprox}
  \leanok
  Every base action has an \( A \)-flexible approximation.
  Hence, every \( \beta \)-action has a flexible approximation, which can be computed branchwise.
\end{proposition}

n32448.content:
\begin{definition}[approximates]
  \uses{def:StrAction,def:ModelData}
  \label{def:StrAction.Approximates}
  We say that a \( \beta \)-action \( \xi \) \emph{approximates} a \( \beta \)-allowable permutation \( \rho \) if \( \xi_A^{\mathcal N}\leq \rho_A^{\mathcal N}\) and \( \xi_A^{\mathcal A}\leq \rho_A^{\mathcal A}\) for each path \( A : \beta \rightsquigarrow\bot \).\footnote{Again, we should define what it means for a base action to approximate a near-litter permutation, and define this in terms of that.}
\end{definition}

n32449.content:
\begin{proposition}
  \uses{def:FlexApprox,def:StrApprox.Approximates,def:StrAction.Approximates}
  \label{prop:FlexApprox.smul_nearLitter_eq}
  \lean{ConNF.BaseAction.smul_nearLitter_of_smul_litter}
  \leanok
  Let \( \xi \) be a base action, and let \( \psi \) be an \( A \)-flexible approximation of it.
  Let \( \pi \) be a base permutation that \( \psi \) exactly approximates.
  If \( (N_1, N_2) \in \xi^{\mathcal N}\) and \( \pi(N_1^\circ) = N_2^\circ \), then \( \pi(N_1) = N_2 \).
\end{proposition}

n32450.content:
\begin{proof}
  \leanok
  First, note that
  \begin{align*}
    \pi[N_1] &= \pi[\operatorname{\mathsf{LS}}(N_1^\circ)] \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\pi[N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_1^\circ)] \\
    &= (\pi[\operatorname{\mathsf{LS}}(N_1^\circ) \cap \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}] \cup \pi[\operatorname{\mathsf{LS}}(N_1^\circ) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}]) \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\pi[N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_1^\circ)]
  \end{align*}
  As \( \psi \) exactly approximates \( \pi \) and \( \pi(N_1^\circ) = N_2^\circ \), we have the equation
  \[ \pi[\operatorname{\mathsf{LS}}(N_1^\circ) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}] = \operatorname{\mathsf{LS}}(N_2^\circ) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}} \]
  Combining this with the fact that \( \psi^{E{\mathcal A}} \leq \pi^{\mathcal A}\), and that \( N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_1^\circ) \subseteq \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}} \), we obtain
  \begin{align*}
    \pi[N_1]
    &= (\operatorname{\mathsf{im}}\psi^{E{\mathcal A}}|_{\operatorname{\mathsf{LS}}(N_1^\circ) \cap \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}} \cup (\operatorname{\mathsf{LS}}(N_2^\circ) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}})) \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{im}}\psi^{E{\mathcal A}}|_{N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_1^\circ)} \\
    &= (\operatorname{\mathsf{im}}\psi^{E{\mathcal A}}|_{\operatorname{\mathsf{LS}}(N_1^\circ) \cap \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}} \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{im}}\psi^{E{\mathcal A}}|_{N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_1^\circ)})  \cup (\operatorname{\mathsf{LS}}(N_2^\circ) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}) \\
    &= \operatorname{\mathsf{im}}\psi^{E{\mathcal A}}|_{(\operatorname{\mathsf{LS}}(N_1^\circ) \cap \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}) \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}(N_1 \mathrel{\raisebox{1pt}{\( \mathsmaller\triangle \)}}\operatorname{\mathsf{LS}}(N_1^\circ))} \cup (\operatorname{\mathsf{LS}}(N_2^\circ) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}) \\
    &= \operatorname{\mathsf{im}}\psi^{E{\mathcal A}}|_{N_1 \cap \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}}} \cup (\operatorname{\mathsf{LS}}(N_2^\circ) \setminus \operatorname{\mathsf{coim}}\psi^{E{\mathcal A}})
  \end{align*}
  which is equal to \( N_2 \) by part of \cref{def:FlexApprox}.
\end{proof}

n32451.content:
\begin{proposition}
  \uses{def:StrApprox.Coherent,def:FlexApprox,def:StrApprox.Approximates,def:StrAction.Approximates}
  \label{prop:approximates_of_flexApprox}
  \lean{ConNF.StrAction.approximates_of_flexApprox_exactlyApproximates}
  \leanok
  Let \( \xi \) be a coherent \( \beta \)-action, and let \( \psi \) be a flexible approximation for it.
  If \( \psi \) exactly approximates some allowable permutation \( \rho \), then \( \xi \) approximates \( \rho \).
\end{proposition}

n32453.content:
\begin{theorem}[freedom of action for actions]
  \uses{def:StrAction.Coherent,def:StrAction.Approximates}
  \label{thm:StrAction.foa}
  \lean{ConNF.StrAction.freedomOfAction}
  \leanok
  Every coherent action approximates some allowable permutation.
\end{theorem}

n32454.content:
\begin{proof}
  \leanok
  \uses{prop:exists_flexApprox,prop:approximates_of_flexApprox,thm:StrApprox.foa}
  Let \( \xi \) be a coherent \( \beta \)-action, and let \( \psi \) be a flexible approximation for it, which exists by \cref{prop:exists_flexApprox}.
  Then apply \cref{thm:StrApprox.foa} (freedom of action) to \( \psi \) to obtain a \( \beta \)-allowable permutation \( \rho \) that \( \psi \) exactly approximates.
  Finally, appeal to \cref{prop:approximates_of_flexApprox} to conclude that \( \xi \) approximates \( \rho \).
\end{proof}

n32455.content:
\begin{definition}
  \uses{def:StrSupport}
  \label{def:StrSupport.Occurs}
  \lean{ConNF.instPreorderSupport}
  \leanok
  We define a preorder \( \preceq \) on base supports by \( S \preceq T \) if and only if \( \operatorname{\mathsf{im}}S^{\mathcal A}\subseteq \operatorname{\mathsf{im}}T^{\mathcal A}\) and \( \operatorname{\mathsf{im}}S^{\mathcal N}\subseteq \operatorname{\mathsf{im}}T^{\mathcal N}\).
  For \( \beta \)-supports, we define \( S \preceq T \) if and only if \( S_A \preceq T_A \) for each \( A \).
\end{definition}

n32456.content:
\begin{definition}
  \uses{def:StrSupport,def:InflexiblePath,def:Interference}
  \label{def:Strong}
  \lean{ConNF.Support.Strong}
  \leanok
  A \( \beta \)-support \( S \) is \emph{strong} if:
  \begin{itemize}
    \item for every pair of near-litters \( N_1, N_2 \in \operatorname{\mathsf{im}}S_A^{\mathcal N}\), we have \( \operatorname{\mathsf{interf}}(N_1, N_2) \subseteq \operatorname{\mathsf{im}}S_A^{\mathcal A}\); and
    \item for every inflexible path \( I = (\gamma,\delta,\varepsilon,A) \) and \( t : \mathsf{Tang}_\delta \), if there is a near-litter \( N \in \operatorname{\mathsf{im}}S_{{A_\varepsilon}_\bot}^{\mathcal N}\) with \( N^\circ = f_{\delta,\varepsilon}(t) \), then \( \operatorname{\mathsf{supp}}(t) \preceq S_{A_\delta} \).
  \end{itemize}
\end{definition}

n32457.content:
\begin{proposition}
  \uses{def:Strong}
  \label{prop:Strong.smul}
  \lean{ConNF.Support.Strong.smul}
  \leanok
  If \( S \) is a strong \( \beta \)-support and \( \rho \) is \( \beta \)-allowable, then \( \rho(S) \) is strong.
\end{proposition}

n32458.content:
\begin{proof}
  \leanok
  Interference is stable under application of allowable permutations, and the required supports are also preserved under action of allowable permutations.
\end{proof}

n32459.content:
\begin{proposition}
  \uses{def:Strong}
  \label{prop:exists_strong}
  \lean{ConNF.Support.strong_strong}
  \leanok
  For every support \( S \), there is a strong support \( T \succeq S \).
\end{proposition}

n32461.content:
\begin{definition}
  \uses{def:StrSupport,def:ModelData}
  \label{def:SupportOrbit}
  For a type index \( \beta \leq \alpha \), a \emph{\( \beta \)-support orbit} is the quotient of \( \mathsf{StrSupp}_\beta \) under the relation of being in the same orbit under \( \beta \)-allowable permutations.\footnote{This can be implemented using \texttt{MulAction.orbitRel.Quotient}. We need to make sure there's plenty of API for support orbits to avoid code duplication.}
\end{definition}

n32462.content:
\begin{definition}
  \uses{def:SupportOrbit}
  \label{def:CodingFunction}
  For any type index \( \beta \leq \alpha \), a \emph{\( \beta \)-coding function} is a relation \( \chi : \mathsf{StrSupp}_\beta \to \mathsf{TSet}_\beta \to \mathsf{Prop}\) such that:
  \begin{itemize}
    \item \( \chi \) is coinjective;
    \item \( \chi \) is nonempty;
    \item if \( (S, x) \in \chi \), then \( S \) is a support for \( x \);
    \item if \( S, T \in \operatorname{\mathsf{coim}}\chi \) then \( S \) and \( T \) are in the same support orbit;
    \item if \( (S, x) \in \chi \) and \( \rho \) is \( \beta \)-allowable, then \( (\rho(S), \rho(x)) \in \chi \).
  \end{itemize}
\end{definition}

n32463.content:
\begin{proposition}[extensionality for coding functions]
  \uses{def:CodingFunction}
  \label{prop:CodingFunction.ext}
  Let \( \chi_1, \chi_2 \) be \( \beta \)-coding functions.
  If \( (S, x) \in \chi_1, \chi_2 \), then \( \chi_1 = \chi_2 \).
\end{proposition}

n32465.content:
\begin{definition}
  \uses{def:CodingFunction}
  \label{def:code}
  Let \( t : \mathsf{Tang}_\beta \).
  Then we define the coding function \( \chi_t \) by the constructor
  \[ \forall \rho : \mathsf{AllPerm}_\beta,\, (\rho(\operatorname{\mathsf{supp}}(t)), \rho(\operatorname{\mathsf{set}}(t))) \in \chi \]
  This is clearly a coding function, and satisfies \( (\operatorname{\mathsf{supp}}(t), \operatorname{\mathsf{set}}(t)) \in \chi_t \).
\end{definition}

n32466.content:
\begin{proposition}
  \uses{def:CodingFunction}
  \label{def:code_eq_code_iff}
  Let \( t, u : \mathsf{Tang}_\beta \).
  Then \( \chi_t = \chi_u \) if and only if there is a \( \beta \)-allowable \( \rho \) with \( \rho(t) = u \).
\end{proposition}

n32467.content:
\begin{proof}
  \uses{prop:CodingFunction.ext}
  If \( \rho(t) = u \), then \( (\operatorname{\mathsf{supp}}(t), \operatorname{\mathsf{set}}(t)) \in \chi_t \) implies \( (\operatorname{\mathsf{supp}}(u), \operatorname{\mathsf{set}}(u)) \in \chi_t \), giving \( \chi_t = \chi_u \) by \cref{prop:CodingFunction.ext}.
  Conversel

n32468.content:
\begin{definition}
  \uses{def:CodingFunction}
  \label{def:Spec}
  An \emph{atom condition} is a pair \( (s, t) \) where \( s, t : \operatorname{\mathsf{Set}}\kappa \).
  A \emph{\( \beta \)-near-litter condition} is either
  \begin{itemize}
    \item a \emph{flexible condition}, consisting of a set \( s : \operatorname{\mathsf{Set}}\kappa \); or
    \item an \emph{inflexible condition}, consisting of an inflexible \( \beta \)-path \( I = (\gamma,\delta,\varepsilon,A) \), a \( \delta \)-coding function \( \chi \), and two \( \delta \)-trees \( R^{\mathcal A}, R^{\mathcal N}\) of relations on \( \kappa \).
  \end{itemize}
  A \emph{\( \beta \)-specification} is a pair \( (\sigma^{\mathcal A}, \sigma^{\mathcal N}) \) where
  \begin{itemize}
    \item \( \sigma^{\mathcal A}\) is a \( \beta \)-tree of enumerations of atom conditions; and
    \item \( \sigma^{\mathcal N}\) is a \( \beta \)-tree of enumerations of \( \beta \)-near-litter conditions.
  \end{itemize}
\end{definition}

n32469.content:
\begin{definition}
  \uses{def:Spec,def:InflexiblePath,def:code}
  \label{def:StrSupport.spec}
  Let \( S \) be a \( \beta \)-support.
  Then \emph{its specification} is the \( \beta \)-specification \( \sigma = \operatorname{\mathsf{spec}}(S) \) given by the following constructors.
  \begin{itemize}
    \item Whenever \( (i, a) \in S_A^{\mathcal A}\), we have \( (i, (s, t)) \in \sigma_A^{\mathcal A}\) where
    \[ s = \{ j : \kappa \mid (j, a) \in S_A^{\mathcal A}\};\quad t = \{ j : \kappa \mid \exists N,\, (j, N) \in S_A^{\mathcal N}\wedge a \in N \} \]
    \item Whenever \( (i, N) \in S_A^{\mathcal N}\) and \( N^\circ \) is \( A \)-flexible, we have \( (i, c) \in \sigma_A^{\mathcal N}\) where \( c \) is the flexible condition given by
    \[ s = \{ j : \kappa \mid \exists N',\, (j, N') \in S_A^{\mathcal N}\wedge N^\circ = {N'}^\circ \} \]
    \item Whenever \( I = (\gamma,\delta,\varepsilon,A) \) is an inflexible \( \beta \)-path, \( t : \mathsf{Tang}_\delta \), and \( (i, N) \in S_{{A_\varepsilon}_\bot}^{\mathcal N}\) is such that \( N^\circ = f_{\delta,\varepsilon}(t) \), we have \( (i, c) \in \sigma_{{A_\varepsilon}_\bot}^{\mathcal N}\) where \( c \) is the inflexible condition given by path \( I \) and coding function \( \chi_t \), and \( R^{\mathcal A}\) and \( R^{\mathcal N}\) are the \( \delta \)-trees of relations given by the constructors
    \begin{align*}
      &\forall i,\, \forall j,\, \forall a,\, (i, a) \in S_{{A_\delta}_B}^{\mathcal A}\to (j, a) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal A}\to (i, j) \in R_B^{\mathcal A}\\
      &\forall i,\, \forall j,\, \forall N,\, (i, N) \in S_{{A_\delta}_B}^{\mathcal N}\to (j, N) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal N}\to (i, j) \in R_B^{\mathcal N}\end{align*}
  \end{itemize}
\end{definition}

n32470.content:
\begin{proposition}
  \uses{def:StrSupport.spec,def:code_eq_code_iff}
  \label{prop:spec_eq_spec_iff}
  Let \( S, T \) be \( \beta \)-supports.
  Then \( \operatorname{\mathsf{spec}}(S) = \operatorname{\mathsf{spec}}(T) \) if and only if\footnote{The following bullet points should comprise a proposition type relating \( S \) and \( T \).}
  \begin{itemize}
    \item \( \operatorname{\mathsf{coim}}S_A^{\mathcal A}= \operatorname{\mathsf{coim}}T_A^{\mathcal A}\) and \( \operatorname{\mathsf{coim}}S_A^{\mathcal N}= \operatorname{\mathsf{coim}}T_A^{\mathcal N}\).
    \item (atom condition) Whenever \( (i, a_1) \in S_A^{\mathcal A}\) and \( (i, a_2) \in T_A^{\mathcal A}\), we have
    \[ \forall j,\, (j, a_1) \in S_A^{\mathcal A}\leftrightarrow (j, a_2) \in T_A^{\mathcal A}\]
    and
    \[ \forall j,\, (\exists N,\, (j, N) \in S_A^{\mathcal N}\wedge a_1 \in N) \leftrightarrow (\exists N,\, (j, N) \in T_A^{\mathcal N}\wedge a_2 \in N) \]
    \item (flexible condition) Whenever \( (i, N_1) \in S_A^{\mathcal N}\) and \( (i, N_2) \in T_A^{\mathcal N}\), if \( N_1^\circ \) is \( A \)-flexible, then so is \( N_2^\circ \), and
    \[ \forall j,\, (\exists N',\, (j, N') \in S_A^{\mathcal N}\wedge N_1^\circ = {N'}^\circ) \leftrightarrow (\exists N',\, (j, N') \in T_A^{\mathcal N}\wedge N_2^\circ = {N'}^\circ) \]
    \item (inflexible condition) Let \( I = (\gamma,\delta,\varepsilon) \) be an inflexible \( \beta \)-path and let \( t : \mathsf{Tang}_\delta \).
    Then whenever \( (i, N_1) \in S_{{A_\varepsilon}_\bot}^{\mathcal N}\) and \( (i, N_2) \in T_{{A_\varepsilon}_\bot}^{\mathcal N}\) are such that \( N_1^\circ = f_{\delta,\varepsilon}(t) \), there is some \( \delta \)-allowable permutation \( \rho \) such that \( N_2^\circ = f_{\delta,\varepsilon}(\rho(t)) \), and
    \begin{align*}
      \forall j,\, \forall a,\, (j, a) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal A}&\to \forall i,\, (i, a) \in S_{{A_\delta}_B}^{\mathcal A}\leftrightarrow (i, \rho_B(a)) \in T_{{A_\delta}_B}^{\mathcal A}\\
      \forall j,\, \forall N,\, (j, N) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal N}&\to \forall i,\, (i, N) \in S_{{A_\delta}_B}^{\mathcal N}\leftrightarrow (i, \rho_B(N)) \in T_{{A_\delta}_B}^{\mathcal N}\end{align*}
  \end{itemize}
\end{proposition}

n32472.content:
\begin{proposition}
  \uses{def:StrSupport.spec}
  \label{prop:spec_smul}
  Let \( \rho \) be \( \beta \)-allowable, and let \( S \) be a \( \beta \)-support.
  Then \( \operatorname{\mathsf{spec}}(\rho(S)) = \operatorname{\mathsf{spec}}(S) \).
\end{proposition}

n32474.content:
\begin{definition}
  \uses{def:BaseSupport}
  \label{def:conv_base}
  Let \( S \) and \( T \) be base supports.
  We define the relations \( \operatorname{\mathsf{conv}}_{S,T}^{\mathcal A}, \operatorname{\mathsf{conv}}_{S,T}^{\mathcal N}\) by the constructors\footnote{This should be abstracted out even further; this can be defined for any pair of relations with common domain.}
  \begin{align*}
    &(i, a_1) \in S^{\mathcal A}\to (i, a_2) \in T^{\mathcal A}\to (a_1, a_2) \in \operatorname{\mathsf{conv}}_{S,T}^{\mathcal A}\\
    &(i, N_1) \in S^{\mathcal N}\to (i, N_2) \in T^{\mathcal N}\to (N_1, N_2) \in \operatorname{\mathsf{conv}}_{S,T}^{\mathcal N}\end{align*}
  Note that \( {\operatorname{\mathsf{conv}}_{S,T}^{\mathcal A}}^{-1} = \operatorname{\mathsf{conv}}_{T,S}^{\mathcal A}\) and \( {\operatorname{\mathsf{conv}}_{S,T}^{\mathcal N}}^{-1} = \operatorname{\mathsf{conv}}_{T,S}^{\mathcal N}\).
\end{definition}

n32475.content:
\begin{proposition}
  \uses{def:conv_base,def:StrSupport.spec}
  \label{prop:conv_one_to_one}
  Let \( S, T \) be supports such that \( \operatorname{\mathsf{spec}}(S) = \operatorname{\mathsf{spec}}(T) \).
  Then \( \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}\) is one-to-one.
\end{proposition}

n32476.content:
\begin{proof}
  \uses{prop:spec_eq_spec_iff}
  If \( (a_1, a_2), (a_1, a_3) \in \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}\), then there are \( i, j \) such that \( (i, a_1), (j, a_1) \in S_A^{\mathcal A}\) and \( (i, a_2), (j, a_3) \in T_A^{\mathcal A}\).
  By \cref{prop:spec_eq_spec_iff}, we deduce \( (j, a_1) \in S_A^{\mathcal A}\leftrightarrow (j, a_2) \in T_A^{\mathcal A}\), so by coinjectivity of \( T_A^{\mathcal A}\), we deduce \( a_2 = a_3 \).
  Hence \( \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}\) is coinjective.
  By symmetry, \( \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}\) is one-to-one.
\end{proof}

n32477.content:
\begin{proposition}
  \uses{def:conv_base,def:StrSupport.spec}
  \label{prop:conv_mem_nearLitter_iff}
  Let \( S, T \) be supports such that \( \operatorname{\mathsf{spec}}(S) = \operatorname{\mathsf{spec}}(T) \).
  If \( (a_1, a_2) \in \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}\) and \( (N_1, N_2) \in \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal N}\), then \( a_1 \in N_1 \) if and only if \( a_2 \in N_2 \).
\end{proposition}

n32478.content:
\begin{proof}
  \uses{prop:spec_eq_spec_iff}
  As \( (a_1, a_2) \in \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}\), there is \( i \) such that \( (i, a_1) \in S_A^{\mathcal A}\) and \( (i, a_2) \in T_A^{\mathcal A}\), and as \( (N_1, N_2) \in \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal N}\), there is \( j \) such that \( (j, N_1) \in S_A^{\mathcal N}\) and \( (j, N_2) \in T_A^{\mathcal N}\).
  By \cref{prop:spec_eq_spec_iff}, we deduce that
  \[ \forall j,\, (\exists N,\, (j, N) \in S_A^{\mathcal N}\wedge a_1 \in N) \leftrightarrow (\exists N,\, (j, N) \in T_A^{\mathcal N}\wedge a_2 \in N) \]
  If \( a_1 \in N_1 \), then as \( (j, N_1) \in S_A^{\mathcal N}\), we deduce that there is a near-litter \( N' \) such that \( (j, N') \in T_A^{\mathcal N}\) and \( a \in N' \).
  But \( T_A^{\mathcal N}\) is coinjective, so \( N' = N_2 \), giving \( a \in N_2 \).
  The converse holds by symmetry.
\end{proof}

n32479.content:
\begin{proposition}
  \uses{def:conv_base,def:StrSupport.spec,def:Strong}
  \label{prop:conv_circ_eq_circ_iff}
  Let \( S, T \) be supports such that \( T \) is strong and \( \operatorname{\mathsf{spec}}(S) = \operatorname{\mathsf{spec}}(T) \).
  If \( (N_1, N_3), (N_2, N_4) \in \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal N}\), then \( N_1^\circ = N_2^\circ \) if and only if \( N_3^\circ = N_4^\circ \).
\end{proposition}

n32480.content:
\begin{proof}
  \uses{prop:spec_eq_spec_iff}
  There are \( i, j \) such that \( (i, N_1), (j, N_2) \in S_A^{\mathcal N}\) and \( (i, N_3), (j, N_4) \in T_A^{\mathcal N}\).
  Suppose that \( N_1^\circ = N_2^\circ \); we show that \( N_3^\circ = N_4^\circ \).

  First, suppose that \( N_1^\circ \) is \( A \)-flexible.
  Then by \cref{prop:spec_eq_spec_iff}, we have
  \[ \forall j,\, (\exists N',\, (j, N') \in S_A^{\mathcal N}\wedge N_1^\circ = {N'}^\circ) \leftrightarrow (\exists N',\, (j, N') \in T_A^{\mathcal N}\wedge N_3^\circ = {N'}^\circ) \]
  So as \( (j, N_2) \in S_A^{\mathcal N}\) and \( N_1^\circ = N_2^\circ \), there is \( N' \) with \( (j, N') \in T_A^{\mathcal N}\) and \( N_3^\circ = {N'}^\circ \), but clearly \( N' = N_4 \), giving the result.

  Now suppose that \( N_1^\circ \) is \( A \)-inflexible, so there is an inflexible \( \beta \)-path \( (\gamma,\delta,\varepsilon,B) \) and tangle \( t : \mathsf{Tang}_\delta \) such that
  \[ A = {B_\varepsilon}_\bot;\quad N_1^\circ = f_{\delta,\varepsilon}(t) \]
  Then by \cref{prop:spec_eq_spec_iff}, there is some \( \delta \)-allowable \( \rho \) such that \( N_3^\circ = f_{\delta,\varepsilon}(\rho(t)) \) and
  \begin{align*}
    \forall j,\, \forall a,\, (j, a) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal A}&\to \forall i,\, (i, a) \in S_{{A_\delta}_B}^{\mathcal A}\leftrightarrow (i, \rho_B(a)) \in T_{{A_\delta}_B}^{\mathcal A}\\
    \forall j,\, \forall N,\, (j, N) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal N}&\to \forall i,\, (i, N) \in S_{{A_\delta}_B}^{\mathcal N}\leftrightarrow (i, \rho_B(N)) \in T_{{A_\delta}_B}^{\mathcal N}\end{align*}
  But as \( N_1^\circ = N_2^\circ \), we draw the same conclusion about \( N_2 \) and \( N_4 \), giving a \( \delta \)-allowable permutation \( \rho' \) such that \( N_4^\circ = f_{\delta,\varepsilon}(\rho'(t)) \); note that the inflexible path and tangle in question will be the same for both pairs.
  We also have
  \begin{align*}
    \forall j,\, \forall a,\, (j, a) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal A}&\to \forall i,\, (i, a) \in S_{{A_\delta}_B}^{\mathcal A}\leftrightarrow (i, \rho'_B(a)) \in T_{{A_\delta}_B}^{\mathcal A}\\
    \forall j,\, \forall N,\, (j, N) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal N}&\to \forall i,\, (i, N) \in S_{{A_\delta}_B}^{\mathcal N}\leftrightarrow (i, \rho'_B(N)) \in T_{{A_\delta}_B}^{\mathcal N}\end{align*}
  Combining these, we obtain
  \begin{align*}
    \forall j,\, \forall a,\, (j, a) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal A}&\to \forall i,\, (i, \rho_B(a)) \in T_{{A_\delta}_B}^{\mathcal A}\leftrightarrow (i, \rho'_B(a)) \in T_{{A_\delta}_B}^{\mathcal A}\\
    \forall j,\, \forall N,\, (j, N) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal N}&\to \forall i,\, (i, \rho_B(N)) \in T_{{A_\delta}_B}^{\mathcal N}\leftrightarrow (i, \rho'_B(N)) \in T_{{A_\delta}_B}^{\mathcal N}\end{align*}
  We claim that \( \rho(\operatorname{\mathsf{supp}}(t)) = \rho'(\operatorname{\mathsf{supp}}(t)) \).
  As \( T \) is strong, for each atom \( a \) such that \( (j, a) \in \operatorname{\mathsf{supp}}(t)_B^{\mathcal A}\), there is some \( k \) such that \( (i, \rho_B(a)) \in T_{{A_\delta}_B}^{\mathcal A}\).
  Thus \( \rho_B(a) = \rho'_B(a) \).
  The same conclusion may be drawn for near-litters.
  Thus \( \rho(\operatorname{\mathsf{supp}}(t)) = \rho'(\operatorname{\mathsf{supp}}(t)) \), giving \( \rho(t) = \rho'(t) \), and hence \( N_3^\circ = N_4^\circ \).
\end{proof}

n32481.content:
\begin{proposition}
  \uses{def:conv_base,def:StrSupport.spec,def:Strong}
  \label{prop:conv_interf}
  Let \( S, T \) be strong supports such that \( \operatorname{\mathsf{spec}}(S) = \operatorname{\mathsf{spec}}(T) \).
  Then for each \( (N_1, N_3), (N_2, N_4) \in \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal N}\),
  \[ \operatorname{\mathsf{interf}}(N_1, N_2) \subseteq \operatorname{\mathsf{coim}}\operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A};\quad \operatorname{\mathsf{interf}}(N_3, N_4) \subseteq \operatorname{\mathsf{im}}\operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}\]
\end{proposition}

n32482.content:
\begin{proof}
  As \( S \) is strong, we have \( \operatorname{\mathsf{interf}}(N_1, N_2) \subseteq \operatorname{\mathsf{im}}S_A^{\mathcal A}\).
  But \( \operatorname{\mathsf{coim}}\operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}= \operatorname{\mathsf{im}}S_A^{\mathcal A}\), as required.\footnote{Make this a lemma.}
  The result for \( \operatorname{\mathsf{interf}}(N_3, N_4) \) then follows by symmetry.
\end{proof}

n32483.content:
\begin{definition}
  \uses{prop:conv_one_to_one,prop:conv_mem_nearLitter_iff,prop:conv_circ_eq_circ_iff,prop:conv_interf}
  \label{def:conv}
  Let \( S, T \) be strong \( \beta \)-supports such that \( \operatorname{\mathsf{spec}}(S) = \operatorname{\mathsf{spec}}(T) \).
  Then for each \( A \), we define the base action \( \operatorname{\mathsf{conv}}_{S_A, T_A} \) to be \( (\operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal A}, \operatorname{\mathsf{conv}}_{S_A, T_A}^{\mathcal N}) \); this is a base action by \cref{prop:conv_one_to_one,prop:conv_mem_nearLitter_iff,prop:conv_circ_eq_circ_iff,prop:conv_interf}.
  We now define the \( \beta \)-action \( \operatorname{\mathsf{conv}}_{S,T} \) by \( (\operatorname{\mathsf{conv}}_{S,T})_A = \operatorname{\mathsf{conv}}_{S_A,T_A} \).
\end{definition}

n32484.content:
\begin{proposition}
  \label{prop:conv_coherent}
  \uses{def:conv}
  Let \( S, T \) be strong supports such that \( \operatorname{\mathsf{spec}}(S) = \operatorname{\mathsf{spec}}(T) \).
  Then \( \operatorname{\mathsf{conv}}_{S,T} \) is coherent.
\end{proposition}

n32486.content:
\begin{proposition}
  \uses{def:StrSupport.spec,def:Strong}
  \label{prop:exists_allowable_of_spec_eq_spec}
  Let \( S, T \) be strong supports such that \( \operatorname{\mathsf{spec}}(S) = \operatorname{\mathsf{spec}}(T) \).
  Then there is an allowable permutation \( \rho \) such that \( \rho(S) = T \).
\end{proposition}

n32487.content:
\begin{proof}
  \uses{prop:conv_coherent,thm:StrAction.foa}
  By \cref{prop:conv_coherent}, we may apply \cref{thm:StrAction.foa} to \( \operatorname{\mathsf{conv}}_{S,T} \) to obtain an allowable permutation \( \rho \) that \( \operatorname{\mathsf{conv}}_{S,T} \) approximates, which directly gives \( \rho(S) = T \) as required.
\end{proof}

n32488.content:
\begin{definition}
  \uses{def:CodingFunction,def:CoherentData}
  \label{def:Combination}
  Let \( \gamma < \beta \) be proper type indices at most \( \alpha \).
  An object \( x : \mathsf{TSet}_\beta \) is called a \emph{\( \gamma \)-combination} of a set of \( \beta \)-coding functions \( s \) with respect to a \( \beta \)-support \( S \) if
  \[ U_\beta(x)(\gamma) = \bigcup_{(V, v) \in \chi \in s,\, V \geq S} U_\beta(v)(\gamma) \]
  By extensionality, a set of coding functions \( s \) has at most one \( \gamma \)-combination with respect to a given support \( S \).
\end{definition}

n32489.content:
\begin{proposition}
  \uses{def:Combination}
  \label{prop:Combination.smul}
  If \( x \) is a \( \gamma \)-combination of \( s \) with respect to \( S \) then \( \rho(x) \) is a \( \gamma \)-combination of \( s \) with respect to \( \rho(S) \).
\end{proposition}

n32490.content:
\begin{proof}
  We can calculate
  \begin{align*}
    U_\beta(\rho(x))(\gamma)
    &= \rho_\gamma[U_\beta(x)(\gamma)] \\
    &= \rho_\gamma\left[ \bigcup_{(V, v) \in \chi \in s,\, V \geq S} U_\beta(v)(\gamma) \right] \\
    &= \bigcup_{(V, v) \in \chi \in s,\, V \geq S} \rho_\gamma\left[ U_\beta(v)(\gamma) \right] \\
    &= \bigcup_{(V, v) \in \chi \in s,\, V \geq S} U_\beta(\rho(v))(\gamma) \\
    &= \bigcup_{(V, v) \in \chi \in s,\, V \geq \rho(S)} U_\beta(v)(\gamma)
  \end{align*}
  where the last inequality uses the fact that coding functions are defined on a support orbit.
\end{proof}

n32491.content:
\begin{definition}
  \uses{def:Combination,def:SupportOrbit}
  \label{def:raisedCodingFunction}
  Let \( s \) be a set of \( \beta \)-coding functions, and let \( o \) be a \( \beta \)-support orbit such that for each \( S \in o \), \( s \) has a \( \gamma \)-combination \( x \) with respect to \( S \) where \( S \) supports \( x \).
  Then the \emph{\( (\gamma,\beta) \)-raised coding function} for \( (s, o) \) is the relation \( \chi : \mathsf{StrSupp}_\beta \to \mathsf{TSet}_\beta \to \mathsf{Prop}\) defined by the constructor
  \[ \forall S \in o,\, \forall x \text{ combinations of } (s, S),\, (S, x) \in \chi \]
\end{definition}

n32492.content:
\begin{proposition}
  \uses{def:raisedCodingFunction}
  \label{prop:raisedCodingFunction_spec}
  The \( (\gamma,\beta) \)-raised coding function for \( (s, o) \) is a coding function.
\end{proposition}

n32493.content:
\begin{proof}
  \uses{prop:Combination.smul}
  Coinjectivity follows from uniqueness of combinations.
  The nonemptiness and support orbit conditions follow from the definition, as does the condition that \( (S, x) \in \chi \) implies that \( S \) is a support for \( x \).
  It remains to show that if \( (S, x) \in \chi \) and \( \rho \) is \( \beta \)-allowable, then \( (\rho(S), \rho(x)) \in \chi \), and this follows directly from \cref{prop:Combination.smul}.
\end{proof}

n32494.content:
\begin{definition}[designated support]
  \uses{def:ModelData}
  \label{def:designatedSupport}
  For a type index \( \beta \leq \alpha \), a \emph{\( \beta \)-set orbit} is the quotient of \( \mathsf{TSet}_\beta \) under the relation of being in the same orbit under \( \beta \)-allowable permutations.
  We write \( [x] \) for the set orbit of \( x \).
  For each set orbit \( o \), we choose a representative \( \operatorname{\mathsf{repr}}(o) : \mathsf{TSet}_\beta \) with \( [\operatorname{\mathsf{repr}}(o)] = o \), and define a support \( S_o \) for \( \operatorname{\mathsf{repr}}(o) \).
  For each set, we choose a \( \beta \)-allowable permutation \( \operatorname{\mathsf{twist}}_t \) with the property that \( \operatorname{\mathsf{twist}}_t(\operatorname{\mathsf{repr}}([t])) = t \), and we define the \emph{designated support} of \( t \) to be \( \operatorname{\mathsf{dsupp}}(t) = \operatorname{\mathsf{twist}}_t(S_{[t]}) \).
  This is a support for \( t \).
\end{definition}

n32495.content:
\begin{definition}
  \uses{def:designatedSupport}
  \label{def:raisedSingleton}
  Let \( \gamma < \beta \) be proper type indices.
  Let \( S \) be a \( \beta \)-support and let \( u : \mathsf{TSet}_\gamma \).
  Then the \emph{\( (\gamma,\beta ) \)-raised singleton} coding function is
  \[ \operatorname{\mathsf{raise}}(S, u) = \chi_{(\operatorname{\mathsf{singleton}}_\beta(u), S + \operatorname{\mathsf{dsupp}}(u)^\beta)} \]
  A coding function is called a \emph{\( (\gamma,\beta) \)-raised singleton} if it is of the form \( \operatorname{\mathsf{raise}}(S, u) \).
\end{definition}

n32496.content:
\begin{proposition}
  \uses{def:raisedSingleton}
  \label{prop:raise_combination}
  Let \( \gamma < \beta \) be proper type indices, and let \( x : \mathsf{TSet}_\beta \).
  Then for any support \( S \) of \( x \), \( x \) is a combination of the set
  \[ \{ \operatorname{\mathsf{raise}}(S, u) \mid u \in U_\beta(x)(\gamma) \} \]
\end{proposition}

n32498.content:
\begin{proposition}
  \uses{def:raisedSingleton,prop:raisedCodingFunction_spec}
  \label{prop:recode}
  Let \( \gamma < \beta \) be proper type indices, and let \( \chi \) be a \( \beta \)-coding function.
  Then there is a set of \( (\gamma,\beta) \)-raised singletons \( s \) and support orbit \( o \) such that \( \chi \) is the \( (\gamma,\beta) \)-raised coding function for \( (s, o) \).
\end{proposition}

n32499.content:
\begin{proof}
  \uses{prop:raise_combination}
  Let \( \chi \) be a \( \beta \)-coding function, and let \( (S, x) \in \chi \).
  Let
  \[ s = \{ \operatorname{\mathsf{raise}}(S, u) \mid u \in U_\beta(x)(\gamma) \} \]
  Let \( o \) be the support orbit such that \( T \in o \) if and only if \( T \in \operatorname{\mathsf{coim}}\chi \).
  We claim that \( \chi \) is the raised coding function for \( (s, o) \).
  It suffices to show that \( (S, x) \) is in this raised coding function.
  That is, we must show that \( S \in o \), which is trivial, and that \( x \) is a combination of \( s \), which is the content of \cref{prop:raise_combination}.
\end{proof}

n32500.content:
\begin{proposition}[the swap permutation]
  \uses{def:BaseSupport,def:Interference}
  \label{prop:exists_swap}
  Let \( S \) be a base support that is closed under interference of near-litters.
  Let \( a_1, a_2 \) be atoms not in \( \operatorname{\mathsf{im}}S^{\mathcal A}\) such that
  \[ \forall N \in \operatorname{\mathsf{im}}S^{\mathcal N},\, a_1 \in N \leftrightarrow a_2 \in N \]
  Then there is a base permutation \( \pi \) that fixes \( S \) and maps \( a_1 \) to \( a_2 \).
\end{proposition}

n32502.content:
\begin{proposition}
  \uses{def:BaseSupport,def:Interference}
  \label{prop:supports_atoms_iff}
  Let \( S \) be a base support that is closed under interference of near-litters.
  Suppose that \( S \) supports a set \( s : \operatorname{\mathsf{Set}}{\mathcal A}\) under the action of base permutations.
  Then for every pair of atoms \( a_1, a_2 \), the statements
  \[ a_1, a_2 \notin \operatorname{\mathsf{im}}S^{\mathcal A}\]
  and
  \[ \forall N \in \operatorname{\mathsf{im}}S^{\mathcal N},\, a_1 \in N \leftrightarrow a_2 \in N \]
  imply that \( a_1 \in s \leftrightarrow a_2 \in s \).
\end{proposition}

n32503.content:
\begin{proof}
  \uses{prop:exists_swap}
  Let \( a_1, a_2 \) be atoms that satisfy the two statements.
  By \cref{prop:exists_swap}, there is a base permutation \( \pi \) that fixes \( S \) and maps \( a_1 \) to \( a_2 \).
  As \( S \) supports \( s \), we obtain \( \pi(s) = s \).
  So \( a_1 \in s \) if and only if \( a_2 \in s \), as required.
\end{proof}

n32504.content:
\begin{proposition}
  \uses{def:BaseSupport,def:BasePerm}
  \label{prop:card_supports_atoms}
  Let \( S \) be a base support.
  Then \( S \) supports at most \( 2^{\#\kappa} \)-many sets \( s : \operatorname{\mathsf{Set}}{\mathcal A}\) under the action of base permutations.
\end{proposition}

n32506.content:
\begin{proposition}
  \uses{def:Spec}
  \label{prop:card_spec}
  Suppose that for all type indices \( \delta < \beta \), there are strictly less than \( \#\mu \)-many \( \delta \)-coding functions.
  Then there are less than \( \#\mu \) \( \beta \)-specifications.
\end{proposition}

n32508.content:
\begin{definition}
  \uses{def:Spec}
  \label{def:WeakSpec}
  A \emph{weak \( \beta \)-specification} is a triple \( W = (R^{\mathcal A}, R^{\mathcal N}, \sigma) \) where \( R^{\mathcal A}, R^{\mathcal N}\) are \( \beta \)-trees of relations on \( \kappa \), and \( \sigma \) is a \( \beta \)-specification.
  We say that a weak specification \emph{specifies} a support \( S \) if there is a strong support \( T \) such that \( \sigma = \operatorname{\mathsf{spec}}(T) \), \( S \preceq T \), and
  \begin{align*}
    (i, j) \in R_A^{\mathcal A}&\leftrightarrow \exists a,\, (i, a) \in S_A^{\mathcal A}\wedge (j, a) \in T_A^{\mathcal A}\\
    (i, j) \in R_A^{\mathcal N}&\leftrightarrow \exists N,\, (i, N) \in S_A^{\mathcal N}\wedge (j, N) \in T_A^{\mathcal N}\end{align*}
\end{definition}

n32509.content:
\begin{proposition}
  \uses{def:WeakSpec}
  \label{prop:exists_weakSpec}
  Every support has a weak specification that specifies it.
\end{proposition}

n32510.content:
\begin{proof}
  \uses{prop:exists_strong}
  Let \( S \) be a support, and let \( T \) be a strong support such that \( S \preceq T \), which exists by \cref{prop:exists_strong}.
  Then simply define \( R^{\mathcal A}\) and \( R^{\mathcal N}\) to be the required relations.
\end{proof}

n32511.content:
\begin{proposition}
  \uses{def:WeakSpec}
  \label{prop:exists_allowable_of_weakSpec}
  If \( W \) is a weak specification that specifies supports \( S \) and \( T \), then there is an allowable permutation \( \rho \) such that \( \rho(S) = T \).
\end{proposition}

n32512.content:
\begin{proof}
  \uses{prop:exists_allowable_of_spec_eq_spec}
  Let \( W = (R^{\mathcal A}, R^{\mathcal N}, \sigma) \), and let \( U, V \) be strong supports such that \( \operatorname{\mathsf{spec}}(U) = \sigma = \operatorname{\mathsf{spec}}(V) \), \( S \preceq U, T \preceq V \), and
  \begin{align*}
    (\exists a,\, (i, a) \in S_A^{\mathcal A}\wedge (j, a) \in U_A^{\mathcal A}) &\leftrightarrow (\exists a,\, (i, a) \in T_A^{\mathcal A}\wedge (j, a) \in V_A^{\mathcal A}) \\
    (\exists N,\, (i, N) \in S_A^{\mathcal N}\wedge (j, N) \in U_A^{\mathcal N}) &\leftrightarrow (\exists N,\, (i, N) \in T_A^{\mathcal N}\wedge (j, N) \in V_A^{\mathcal N})
  \end{align*}
  By \cref{prop:exists_allowable_of_spec_eq_spec}, there is an allowable permutation \( \rho \) such that \( \rho(U) = V \).
  We claim that \( \rho(S) = T \).
  Suppose \( (i, a) \in S_A^{\mathcal A}\).
  Then as \( S \preceq U \), there is \( j \) such that \( (j, a) \in U_A^{\mathcal A}\).
  So there is \( a' \) such that \( (i, a') \in T_A^{\mathcal A}\) and \( (j, a') \in V_A^{\mathcal A}\).
  Then \( a' = \rho_A(a) \) as \( \rho(U) = V \), as required.
  The same simple calculation gives the required result for near-litters.
\end{proof}

n32513.content:
\begin{proposition}
  \uses{def:WeakSpec}
  \label{prop:card_weakSpec}
  Suppose that for all type indices \( \delta < \beta \), there are strictly less than \( \#\mu \)-many \( \delta \)-coding functions.
  Then there are less than \( \#\mu \) weak \( \beta \)-specifications.
\end{proposition}

n32514.content:
\begin{proof}
  \uses{prop:card_spec}
  Follows directly from \cref{prop:card_spec} and the remark that there are less than \( \#\mu \) \( \beta \)-trees of relations on \( \kappa \).
\end{proof}

n32515.content:
\begin{proposition}
  \uses{def:SupportOrbit,def:CodingFunction}
  \label{prop:card_supportOrbit}
  Suppose that for all type indices \( \delta < \beta \), there are strictly less than \( \#\mu \)-many \( \delta \)-coding functions.
  Then there are less than \( \#\mu \) \( \beta \)-support orbits.
\end{proposition}

n32516.content:
\begin{proof}
  \uses{prop:exists_weakSpec,prop:exists_allowable_of_weakSpec,prop:card_weakSpec}
  Define a function from the type of \( \beta \)-support orbits into the type of weak \( \beta \)-specifications by mapping a representative to a weak specification that specifies it; one will always exist by \cref{prop:exists_weakSpec}.
  This is an injection: if \( o_1, o_2 \) are orbits with representatives \( S_1, S_2 \) and \( S_1, S_2 \) have the same assigned weak specification, then by \cref{prop:exists_allowable_of_weakSpec} there is an allowable permutation \( \rho \) such that \( \rho(S_1) = S_2 \), and so \( o_1 = o_2 \).
  So we are done as there are less than \( \#\mu \) weak \( \beta \)-specifications by \cref{prop:card_weakSpec}.
\end{proof}

n32517.content:
\begin{proposition}
  \uses{def:SupportOrbit,def:CodingFunction}
  \label{prop:card_codingFunction_of_card_supports}
  Let \( \beta \) be a type index (which in practice will be \( \bot \) or the lowest proper type index).
  Suppose that there are less than \( \#\mu \) \( \beta \)-support orbits.
  Let \( \nu \) be a cardinal less than \( \#\mu \) such that for each \( \beta \)-support \( S \), there are at most \( \nu \)-many objects \( x : \mathsf{TSet}_\beta \) that \( S \) supports.
  Then there are less than \( \#\mu \) \( \beta \)-coding functions.
\end{proposition}

n32518.content:
\begin{proof}
  Every \( \beta \)-coding function is of the form \( \chi_{(x, S)} \) where \( S \) is a representative chosen in advance for a support orbit, and \( x \) is an object that \( S \) supports under the action of \( \beta \)-allowable permutations.
  So there are at most
  \[ \sum_{S \text{ representatives}} \nu = \#\{\text{support orbits}\} \cdot \nu \]
  coding functions, which is less than \( \#\mu \).
\end{proof}

n32520.content:
\begin{proof}
  \uses{prop:card_codingFunction_of_card_supports,prop:card_supportOrbit,prop:card_supports_atoms}
  By \cref{prop:card_codingFunction_of_card_supports}, it suffices to show that there are less than \( \#\mu \) \( \bot \)-support orbits and that there is a bound less than \( \#\mu \) on the amount of objects that a given \( \bot \)-support supports.
  The first result follows from \cref{prop:card_supportOrbit}, which has vacuous assumptions in this case.
  The second result follows from applying \cref{prop:card_supports_atoms} to singletons of atoms, after applying the bijections between \( \bot \)-supports and base supports, and between \( \bot \)-allowable permutations and base permutations.
\end{proof}

n32521.content:
\begin{proposition}
  \uses{def:CodingFunction}
  \label{prop:card_codingFunction_min}
  There are less than \( \#\mu \) \( \beta \)-coding functions if \( \beta \) is the minimal inhabitant of \( \lambda \).
\end{proposition}

n32522.content:
\begin{proof}
  \uses{prop:card_codingFunction_of_card_supports,prop:card_supportOrbit,prop:card_codingFunction_bot,prop:card_supports_atoms,def:CoherentData}
  Again, we apply \cref{prop:card_codingFunction_of_card_supports}.
  The first claim follows from \cref{prop:card_supportOrbit}, where this time we use the fact that there are less than \( \#\mu \) \( \bot \)-coding functions (\cref{prop:card_codingFunction_bot}).
  The second claim follows from \cref{prop:card_supports_atoms} to \( \bot \)-extensions of type \( \beta \) objects, noting that \( \beta \)-supports correspond to base supports and that \( \beta \)-allowable permutations correspond to base permutations.\footnote{One useful claim to prove for this is that there is a unique path \( \beta \rightsquigarrow\bot \), and so type \( \beta \) objects satisfy \( \bot \)-extensionality by injectivity of \( U_\beta \).}
  The fact that \( \beta \)-allowable permutations correspond to base permutations relies on the fact that we can construct a \( \beta \)-permutation from a base permutation using coherent data (\cref{def:CoherentData}).
\end{proof}

n32523.content:
\begin{proposition}
  \uses{def:CodingFunction,def:raisedSingleton}
  \label{prop:card_raisedSingleton}
  Suppose that for all type indices \( \delta < \beta \), there are strictly less than \( \#\mu \)-many \( \delta \)-coding functions.
  Then if \( \gamma < \beta \) is a proper type index, there are strictly less than \( \#\mu \) \( (\gamma,\beta) \)-raised singletons.
\end{proposition}

n32525.content:
\begin{proposition}
  \uses{def:CodingFunction}
  \label{prop:card_codingFunction}
  There are less than \( \#\mu \)-many \( \beta \)-coding functions for all type indices \( \beta \leq \alpha \).
\end{proposition}

n32526.content:
\begin{proof}
  \uses{prop:card_codingFunction_bot,prop:card_codingFunction_min,prop:recode,prop:card_supportOrbit,prop:card_raisedSingleton}
  By induction we may assume that for all type indices \( \delta < \beta \), there are strictly less than \( \#\mu \)-many \( \delta \)-coding functions.
  By \cref{prop:card_codingFunction_bot,prop:card_codingFunction_min}, we may assume that \( \beta \) is a proper type index, and that it is not minimal in \( \lambda \), so there is some proper type index \( \gamma < \beta \).
  By \cref{prop:recode}, every \( \beta \)-coding function is determined by a set of \( (\gamma,\beta) \)-raised singletons \( s \) and support orbit \( o \).
  The conclusion then follows from \cref{prop:card_supportOrbit,prop:card_raisedSingleton} and the fact that \( \#\mu \) is a strong limit.
\end{proof}

n32528.content:
\begin{proof}
  \uses{prop:card_codingFunction}
  If \( \beta \) is \( \bot \), we already know \( \#\mathsf{TSet}_\bot = \#{\mathcal A}= \#\mu \), so suppose \( \#\beta \) is a proper type index.
  Each object \( x : \mathsf{TSet}_\beta \) is determined by a \( \beta \)-coding function and a \( \beta \)-support.
  Since there are less than \( \#\mu \)-many \( \beta \)-coding functions (\cref{prop:card_codingFunction}) and there are exactly \( \#\mu \) \( \beta \)-supports, we obtain \( \#\mathsf{TSet}_\beta \leq \#\mu \).
  Since the typed near-litter map \( {\mathcal N}\to \mathsf{TSet}_\beta \) is injective, there are at least \( \#{\mathcal N}= \#\mu \) inhabitants of \( \mathsf{TSet}_\beta \), giving the result by antisymmetry.
\end{proof}

n32530.content:
\begin{proof}
  \uses{prop:card_tSet}
  Use \cref{prop:card_tSet} and the fact that there are precisely \( \#\mu \)-many \( \beta \)-supports.
\end{proof}

n32531.content:
\begin{definition}
  \label{def:IC}
  Let \( I : \mathsf{Type}_u \) be a type with a well-founded transitive relation \( \prec \).
  Let \( A : I \to \mathsf{Type}_v \) be a family of types indexed by \( I \), and let
  \[ B : \prod_{i : I} A_i \to \left(\prod_{j : I} j \prec i \to A_j\right) \to \mathsf{Sort}_w \]
  An \emph{inductive construction} for \( (I, A, B) \) is a pair of functions
  \begin{align*}
    &F_A : \prod_{i : I} \prod_{d : \prod_{j : I} j \prec i \to A_j} \\
    &\quad\left( \prod_{j : I} \prod_{h : j \prec i} B\ j\ (d\ j\ h)\ (k\ h' \mapsto d\ k\ (\operatorname{\mathsf{trans}}(h',h))) \right) \to A_i \\
    &F_B : \prod_{i : I} \prod_{d : \prod_{j : I} j \prec i \to A_j} \\
    &\quad\prod_{h : \left( \prod_{j : I} \prod_{h : j \prec i} B\ j\ (d\ j\ h)\ (k\ h' \mapsto d\ k\ (\operatorname{\mathsf{trans}}(h',h))) \right)} B\ i\ (F_A\ i\ d\ h)\ d
  \end{align*}
\end{definition}

n32532.content:
\begin{proposition}[inductive construction theorem for propositions]
  \uses{def:IC}
  \label{prop:IC.fix_prop}
  Let \( (F_A, F_B) \) be an inductive construction for \( (I, A, B) \), where \( w \) is \( 0 \).
  Then there are computable functions
  \[ G : \prod_{i : I} A_i;\quad H : \prod_{i : I} B\ i\ G_i\ (j\ \_ \mapsto G_j) \]
  such that for each \( i : I \),
  \[ G_i = F_A\ i\ (j\ \_ \mapsto G_j)\ (F_B\ i\ (j\ \_ \mapsto H_j)) \]
\end{proposition}

n32535.content:
\begin{proof}
  \uses{prop:IC.fix_prop}
  Define
  \[ C : \prod_{i : I} A_i \to \left(\prod_{j : I} j \prec i \to A_j\right) \to \mathsf{Prop}\]
  by \( C\ i\ x\ d = \operatorname{\mathsf{Nonempty}}(B\ i\ x\ d) \).
  We then define the inductive construction \( (F_A', F_B') \) for \( (I, A, C) \) by
  \[ F_A'\ i\ d\ h = F_A\ i\ d\ (j h' \mapsto \operatorname{\mathsf{some}}(h\ j\ h'));\quad F_B'\ i\ d\ h = \langle F_B\ i\ d\ (j h' \mapsto \operatorname{\mathsf{some}}(h\ j\ h')) \rangle \]
  where \( \langle-\rangle \) is the constructor and \( \operatorname{\mathsf{some}} \) is the noncomputable destructor of \( \operatorname{\mathsf{Nonempty}} \).
  The result is then direct from \cref{prop:IC.fix_prop}.
\end{proof}

n32537.content:
\begin{definition}
  \uses{def:MainMotive,def:TypedNearLitter,def:InflexiblePath}
  \label{def:MainHypothesis}
  We define the \emph{main hypothesis}
  \[ \mathsf{Hypothesis}: \prod_{\alpha : \lambda} \mathsf{Motive}_\alpha \to \left( \prod_{\beta < \alpha} \mathsf{Motive}_\beta \right) \to \mathsf{Type}_{u+1} \]
  at \( \alpha \), given \( \mathsf{Motive}_\alpha \) and \( \prod_{\beta < \alpha} \mathsf{Motive}_\beta \), to be the type consisting of the following data.
  \begin{itemize}
    \item For \( \gamma < \beta \leq \alpha \), there is a map \( \mathsf{AllPerm}_\beta \to \mathsf{AllPerm}_\gamma \) that commutes with the coercions from \( \mathsf{AllPerm}_{(-)} \) to \( \mathsf{StrPerm}_{(-)} \).
    \item Let \( \beta, \gamma < \alpha \) be distinct with \( \gamma \) proper.
    Let \( t : \mathsf{Tang}_\beta \) and \( \rho : \mathsf{AllPerm}_\alpha \).
    Then
    \[ (\rho_\gamma)_\bot(f_{\beta,\gamma}(t)) = f_{\beta,\gamma}(\rho_\beta(t)) \]
    \item Suppose that \( (\rho(\beta))_{\beta < \alpha} \) is a collection of allowable permutations such that whenever \( \beta, \gamma < \alpha \) are distinct, \( \gamma \) is proper, and \( t : \mathsf{Tang}_\gamma \), we have
    \[ (\rho(\gamma))_\bot(f_{\beta,\gamma}(t)) = f_{\beta,\gamma}(\rho(\beta)(t)) \]
    Then there is an \( \alpha \)-allowable permutation \( \rho \) with \( \rho_\beta = \rho(\beta) \) for each \( \beta < \alpha \).
    \item For any \( \beta < \alpha \),
    \[ U_\alpha(x)(\beta) \subseteq \operatorname{\mathsf{ran}}U_\beta \]
    \item (extensionality) If \( \beta : \lambda \) is such that \( \beta < \alpha \), the map \( U_\alpha(-)(\beta) : \mathsf{TSet}_\beta \to \operatorname{\mathsf{Set}}\mathsf{StrSet}_\beta \) is injective.
    \item If \( \beta : \lambda \) is such that \( \beta < \alpha \), for every \( x : \mathsf{TSet}_\beta \) there is some \( y : \mathsf{TSet}_\alpha \) such that \( U_\alpha(y)(\beta) = \{ x \} \), and we write \( \operatorname{\mathsf{singleton}}_\alpha(x) \) for this object \( y \).
  \end{itemize}
\end{definition}

n32538.content:
\begin{definition}
  \uses{def:MainMotive,def:NewModelData,def:CoherentData,prop:card_tangle,prop:newPos}
  \label{def:motiveStep}
  The \emph{inductive step for the main motive} is the function
  \begin{align*}
    &\operatorname{\mathsf{Step}}_M : \prod_{\alpha : \lambda} \prod_{M : \prod_{\beta < \alpha} \mathsf{Motive}_\beta} \\
    &\quad\left( \prod_{\beta : \lambda} \prod_{h : \beta < \alpha} \mathsf{Hypothesis}\ \beta\ (M\ \beta\ h)\ (\gamma\ h' \mapsto M\ \gamma\ (\operatorname{\mathsf{trans}}(h',h))) \right) \to \mathsf{Motive}_\alpha
  \end{align*}
  given as follows.
  Given the hypotheses \( \alpha, M, H \), we use \cref{def:NewModelData} to construct model data at level \( \alpha \).
  Then, combine this with \( H \) to create an instance of coherent data below level \( \alpha \).\footnote{This requires using the definition of new allowable permutations. There may be some difficulties here in converting between the types of model data at level \( \alpha \) together with model data at all \( \beta < \alpha \), and model data at all levels \( \beta \leq \alpha \).}
  By \cref{prop:card_tangle}, we conclude that \( \#\mathsf{Tang}_\alpha = \#\mu \), and so by \cref{prop:newPos} there is a position function on \( \mathsf{Tang}_\alpha \) that respects the typed near-litters defined in \cref{def:newTypedNearLitter}.
  These data comprise the main motive at level \( \alpha \).
\end{definition}

n32539.content:
\begin{definition}
  \uses{def:MainHypothesis,def:motiveStep,def:newSingleton}
  \label{def:hypothesisStep}
  The \emph{inductive step for the main hypothesis} is the function
  \begin{align*}
    &\operatorname{\mathsf{Step}}_H : \prod_{\alpha : \lambda} \prod_{M : \prod_{\beta < \alpha} \mathsf{Motive}_\beta} \\
    &\quad\prod_{H : \prod_{\beta : \lambda} \prod_{h : \beta < \alpha} \mathsf{Hypothesis}\ \beta\ (M\ \beta\ h)\ (\gamma\ h' \mapsto M\ \gamma\ (\operatorname{\mathsf{trans}}(h',h)))}\\
    &\quad\mathsf{Hypothesis}\ \alpha\ (\operatorname{\mathsf{Step}}_M\ \alpha\ M\ H)\ M
  \end{align*}
  given as follows.
  Given the hypotheses \( \alpha, M, H \), we use the definitions from \cref{def:motiveStep} to obtain model data at level \( \alpha \) and coherent data below level \( \alpha \).
  The remaining proof obligations are handled by \cref{def:newSingleton,prop:newPos}.
\end{definition}

n32540.content:
\begin{theorem}[model construction]
  \uses{def:motiveStep,def:hypothesisStep}
  \label{thm:model_construction}
  There are noncomputable functions
  \[ \operatorname{\mathsf{ComputeMotive}} : \prod_{\alpha : \lambda} \mathsf{Motive}_\alpha \]
  and
  \[ \operatorname{\mathsf{ComputeHypothesis}} : \prod_{\alpha : \lambda} \mathsf{Hypothesis}\ \alpha\ \operatorname{\mathsf{ComputeMotive}}_\alpha\ (\beta\ \_ \mapsto \operatorname{\mathsf{ComputeMotive}}_\beta) \]
  such that for each \( \alpha : \lambda \),
  \begin{align*}
    \operatorname{\mathsf{ComputeMotive}}_\alpha = &\operatorname{\mathsf{Step}}_M\ \alpha\ (\beta\ \_ \mapsto \operatorname{\mathsf{ComputeMotive}}_\beta)\\
    &(\operatorname{\mathsf{Step}}_H\ \alpha\ (\beta\ \_ \mapsto \operatorname{\mathsf{ComputeHypothesis}}_\beta))
  \end{align*}
\end{theorem}

n32542.content:
\begin{proposition}
  \uses{prop:exists_strong}
  \label{prop:raiseStrong_length}
  Let \( T \) be a \( \gamma \)-support, and let \( U \) be the strong support generated by \( T^\beta \).
  If \( A \) is a path such that \( \operatorname{\mathsf{im}}U_A^{\mathcal N}\) is nonempty, then \( A \) has length at least 2.
\end{proposition}

n32543.content:
\begin{proof}
  Let \( N \in \operatorname{\mathsf{im}}U_A^{\mathcal N}\).
  Either \( A \) is of the form \( B^\beta \) for \( B : \gamma \rightsquigarrow\bot \) and \( N \in \operatorname{\mathsf{im}}T_B^{\mathcal N}\), in which case \( B \) clearly has length at least 2 as \( \gamma \) is a proper type index, or \( N \in \operatorname{\mathsf{im}}V_B^{\mathcal N}\) where \( A = B^\beta \) and \( B : \delta \rightsquigarrow\bot \), and \( V \) supports some \( \delta \)-set.
  But we cannot have \( \delta = \bot \), because \( \bot \)-supports that support some \( \delta \)-set cannot contain near-litters, so in this other case \( A \) also has length at least 2.
\end{proof}

n32544.content:
\begin{proposition}
  \uses{prop:exists_strong}
  \label{prop:raiseStrong}
  Let \( T \) be a \( \gamma \)-support, and let \( U \) be the strong support generated by \( T^\beta \).
  Then \( U^\alpha \) is strong.
\end{proposition}

n32546.content:
\begin{proposition}
  \uses{prop:exists_strong}
  \label{prop:raiseRaise_strong}
  Let \( S \) be a strong \( \alpha \)-support and let \( T \) be a \( \gamma \)-support.
  Let \( U \) be the strong support generated by \( T^\beta \), and let \( V \) be the support whose image is precisely those atoms in the interference of \( S_\beta \) and \( U \).
  Let \( \rho \) be a \( \beta \)-allowable permutation that fixes \( S_\beta \).
  Then \( S + (\rho(U + V))^\alpha \) is strong.
\end{proposition}

n32548.content:
\begin{proposition}
  \label{prop:combineStrong}
  Let \( S \) be a strong \( \alpha \)-support.
  Let \( U \) be a strong \( \beta \)-support with the property that if \( A \) is a path such that \( \operatorname{\mathsf{im}}U_A^{\mathcal N}\) is nonempty, then \( A \) has length at least 2.
  Then for every \( \beta \)-allowable \( \rho \) that fixes \( S_\beta \), we have \( \operatorname{\mathsf{spec}}(S + U^\alpha) = \operatorname{\mathsf{spec}}(S + (\rho(U))^\alpha) \).
\end{proposition}

n32549.content:
\begin{proof}
  Appeal to \cref{prop:spec_eq_spec_iff}.
  First, note that \( (i, a) \in (S + (\rho(U))^\alpha)_A^{\mathcal A}\) if and only if \( (i, a) \in S \) or \( A = B^\alpha \) and \( (i, a) \in \rho(U)_B^{\mathcal A}\).
  Thus,
  \begin{align*}
    (i, a_1) \in (S + U^\alpha)_A^{\mathcal A}&\to \exists a_2,\, (i, a_2) \in (S + (\rho(U))^\alpha)_A^{\mathcal A}\\
    &\quad\wedge [(\exists B,\, A = B^\alpha \wedge \rho_B(a_1) = a_2) \vee ((\forall B,\, A \neq B^\alpha) \wedge a_1 = a_2)]
  \end{align*}
  and the same holds for the other direction\footnote{We can prove the other direction easily from this by substituting \( \rho(U) \) and \( \rho^{-1} \).} and for near-litters.

  The coimage condition is clear.
  Suppose that \( (i, a_1) \in (S + U^\alpha)_A^{\mathcal A}\) and \( (i, a_2) \in (S + (\rho(U))^\alpha)_A^{\mathcal A}\).
  Then by coinjectivity we can apply the above result, giving that either there is \( B \) such that \( A = B^\alpha \) and \( \rho_B(a_1) = a_2 \), or there is no such \( B \), and \( a_1 = a_2 \).
  In either case, the result is easy to show.

  The result for litters follows from the fact that the condition on \( U \) implies that proofs of inflexiblity of litters in \( U \) correspond bijectively to proofs of inflexibility of litters in \( U^\alpha \).\footnote{TODO: Probably want more details when we get here.}
\end{proof}

n32550.content:
\begin{proposition}
  \uses{def:Strong}
  \label{prop:exists_allowable_of_fixes}
  Let \( S \) be a strong \( \alpha \)-support and let \( T \) be a \( \gamma \)-support.
  Let \( \rho \) be a \( \beta \)-allowable permutation that fixes \( S_\beta \).
  Then there is an \( \alpha \)-allowable permutation \( \rho' \) such that
  \[ \rho'(S) = S;\quad (\rho'_\beta)_\gamma(T) = \rho_\gamma(T) \]
\end{proposition}

n32551.content:
\begin{proof}
  \uses{prop:exists_allowable_of_spec_eq_spec,prop:raiseRaise_strong,prop:raiseStrong_length,prop:combineStrong}
  Let \( U \) be the strong support generated by \( T^\beta \), and let \( V \) be the support whose image is precisely those atoms in the interference of \( S_\beta \) and \( U \).
  Then apply \cref{prop:exists_allowable_of_spec_eq_spec,prop:raiseRaise_strong,prop:raiseStrong_length,prop:combineStrong}.
\end{proof}

n32552.content:
\begin{definition}[tangled membership]
  \uses{thm:model_construction}
  \label{def:TSet.mem}
  We define the membership relation \( \in^\alpha_\beta : \mathsf{TSet}_\beta \to \mathsf{TSet}_\alpha \to \mathsf{Prop}\) by
  \[ x \in^\alpha_\beta y \leftrightarrow U_\beta(x) \in U_\alpha(y)(\beta) \]
  Extensionality holds at all proper type indices by \cref{prop:Code.ext}.
  Also, for every \( \alpha \)-allowable \( \rho \), we have
  \[ \rho_\beta(x) \in^\alpha_\beta \rho(y) \leftrightarrow x \in^\alpha_\beta y \]
\end{definition}

n32553.content:
\begin{definition}[symmetric]
  \uses{thm:model_construction}
  \label{def:Symmetric}
  Let \( \beta < \alpha \) be proper type indices.
  A set \( s : \mathsf{TSet}_\beta \) is called \emph{\( \alpha \)-symmetric} if there is some \( \alpha \)-support \( S \) such that if \( \rho \) is an \( \alpha \)-allowable permutation that fixes \( S \), then \( \rho \) fixes \( s \) setwise.
  Note that it suffices to prove that for all \( \rho \) that fix \( S \), \( s \subseteq \rho[s] \) (or alternatively, \( \rho[s] \subseteq s \)).
  Every small set is symmetric, since a support can be obtained by raising the types of chosen supports for elements of the set and then collating the results.
\end{definition}

n32554.content:
\begin{proposition}
  \uses{def:Symmetric}
  \label{prop:TSet.of_symmetric}
  Let \( \beta < \alpha \) be proper type indices.
  Let \( s : \mathsf{TSet}_\beta \) be \( \alpha \)-symmetric.
  Then there is \( x : \mathsf{TSet}_\alpha \) such that
  \[ \forall y : \mathsf{TSet}_\beta,\, y \in_\beta^\alpha x \leftrightarrow y \in s \]
  Moreover, every \( x : \mathsf{TSet}_\alpha \) arises in this way; this is an induction principle for \( \mathsf{TSet}_\alpha \).
\end{proposition}

n32556.content:
\begin{proposition}[unions of singletons]
  \uses{thm:model_construction}
  \label{prop:singleton_union}
  Let \( \gamma < \beta < \alpha \) be proper type indices.
  Let \( s : \operatorname{\mathsf{Set}}\mathsf{TSet}_\gamma \) be such that \( \operatorname{\mathsf{singleton}}_\beta[s] \) is \( \alpha \)-symmetric.
  Then \( s \) is \( \beta \)-symmetric.
\end{proposition}

n32558.content:
\begin{theorem}[consistency of tangled type theory]
  \uses{def:TSet.mem}
  \label{thm:ttt_consistent}
  Let \( \{ x \}_\beta \) be an abbreviation for \( \operatorname{\mathsf{singleton}}_\beta(x) \), and let \( \langle x, y \rangle_{\gamma,\beta} \) be an abbreviation for \( \{ \{ x \}_\gamma, \{ x, y \}_\gamma \}_\beta \).
  Then, the following axioms hold for our model \( \mathsf{TSet}\) at all sequences of proper type indices \( \zeta < \varepsilon < \delta < \gamma < \beta < \alpha \).
  \begin{center}
    \begin{tabular}{llcl}
      \( - \) & extensionality & \( \forall x^\alpha,\, \forall y^\alpha,\, (\forall z^\beta,\, z \in x \leftrightarrow z \in y) \to x = y \) \\
      P1(a) & intersection & \( \forall x^\alpha y^\alpha,\, \exists z^\alpha,\, \forall w^\beta,\, w \in z \leftrightarrow (w \in x \wedge w \in y) \) \\
      P1(b) & complement & \( \forall x^\alpha,\, \exists z^\alpha,\, \forall w^\beta,\, w \in z \leftrightarrow w \notin x \) \\
      \( - \) & singleton & \( \forall x^\beta,\, \exists y^\alpha,\, \forall z^\beta,\, z \in y \leftrightarrow z = x \) \\
      P2 & singleton image & \( \forall x^\beta,\, \exists y^\alpha,\, \forall z^\varepsilon w^\varepsilon,\, \langle \{ z \}_\delta, \{ w \}_\delta \rangle_{\gamma,\beta} \in y \leftrightarrow \langle z, w \rangle_{\delta,\gamma} \in x \) \\
      P3 & insertion two & \( \forall x^\gamma,\, \exists y^\alpha,\, \forall z^\zeta w^\zeta t^\zeta,\, \langle \{ \{ z \}_\varepsilon \}_\delta, \langle w, t \rangle_{\varepsilon, \delta} \rangle_{\gamma,\beta} \in y \leftrightarrow \langle z, t \rangle_{\varepsilon,\delta} \in x \) \\
      P4 & insertion three & \( \forall x^\gamma,\, \exists y^\alpha,\, \forall z^\zeta w^\zeta t^\zeta,\, \langle \{ \{ z \}_\varepsilon \}_\delta, \langle w, t \rangle_{\varepsilon,\delta} \rangle_{\gamma,\beta} \in y \leftrightarrow \langle z, w \rangle_{\varepsilon,\delta} \in x \) \\
      P5 & cross product & \( \forall x^\gamma,\, \exists y^\alpha,\, \forall z^\beta,\, z \in y \leftrightarrow \exists w^\delta t^\delta,\, z = \langle w, t \rangle_{\gamma,\beta} \wedge t \in x \) \\
      P6 & type lowering & \( \forall x^\alpha,\, \exists y^\delta,\, \forall z^\varepsilon,\, z \in y \leftrightarrow \forall w^\delta,\, \langle w, \{ z \}_\delta \rangle_{\gamma,\beta} \in x \) \\
      P7 & converse & \( \forall x^\alpha,\, \exists y^\alpha,\, \forall z^\delta w^\delta,\, \langle z, w \rangle_{\gamma,\beta} \in y \leftrightarrow \langle w, z \rangle_{\gamma,\beta} \in x \) \\
      P8 & cardinal one & \( \exists x^\alpha,\, \forall y^\beta,\, y \in x \leftrightarrow \exists z^\gamma,\, \forall w,\, w \in y \leftrightarrow w = z \) \\
      P9 & subset & \( \exists x^\alpha,\, \forall y^\delta z^\delta,\, \langle y, z \rangle_{\gamma,\beta} \in x \leftrightarrow \forall w^\varepsilon,\, w \in y \to w \in z \)
    \end{tabular}
  \end{center}
\end{theorem}

n32559.content:
\begin{proof}
  \uses{prop:Code.ext,prop:TSet.of_symmetric,prop:singleton_union}
  The axiom of extensionality was proven in \cref{prop:Code.ext}.
  All axioms except for the type lowering axiom can be easily proven using \cref{prop:TSet.of_symmetric}.
  For type lowering, consider the set
  \[ y' = \{ \{\{\{z^\varepsilon\}_\delta\}_\gamma\}_\beta \mid \forall w^\delta,\, \langle w, \{ z \}_\delta \rangle_{\gamma,\beta} \in x \} \]
  which exists by \cref{prop:TSet.of_symmetric}, and then apply \cref{prop:singleton_union} three times.
\end{proof}

n32560.content:
\begin{definition}
  A \emph{\( \Sigma \)-language} consists of a map \( \operatorname{\mathsf{Functions}} : \prod_{n : \mathbb N} (\operatorname{\mathsf{Fin}}n \to \Sigma) \to \Sigma \to \mathsf{Type}_u \) and a map \( \operatorname{\mathsf{Relations}} : \prod_{n : \mathbb N} (\operatorname{\mathsf{Fin}}n \to \Sigma) \to \mathsf{Type}_v \).
\end{definition}

n32561.content:
\begin{definition}
  Let \( \Phi : \Sigma \to \Sigma' \).
  Let \( L \) be a \( \Sigma \)-language and let \( L' \) be a \( \Sigma' \)-language.
  Then a \emph{\( \Phi \)-morphism} of languages \( L \xrightarrow \Phi L' \) consists of a map
  \[ \operatorname{\mathsf{onFunction}} : \prod_{n : \mathbb N} \prod_{A : \operatorname{\mathsf{Fin}}n \to \Sigma} \prod_{B : \Sigma} \operatorname{\mathsf{Functions}}_L(n, A, B) \to \operatorname{\mathsf{Functions}}_{L'}(\Phi \circ A, \Phi(B)) \]
  and a map
  \[ \operatorname{\mathsf{onRelation}} : \prod_{n : \mathbb N} \prod_{A : \operatorname{\mathsf{Fin}}n \to \Sigma} \operatorname{\mathsf{Relations}}_L(n, A) \to \operatorname{\mathsf{Functions}}_{L'}(\Phi \circ A) \]
  If \( L, L' \) are \( \Sigma \)-languages, we may simply say that a \emph{morphism} of languages \( L \to L' \) is a \( \operatorname{\mathsf{id}}_\Sigma \)-morphism \( L \xrightarrow{\operatorname{\mathsf{id}}_\Sigma} L' \).\footnote{It is crucial that \( \operatorname{\mathsf{id}}\circ f \equiv f \circ \operatorname{\mathsf{id}}\equiv f \) definitionally.}
\end{definition}

n32565.content:
\begin{definition}
  Let \( L \) be a \( \Sigma \)-language, and let \( \alpha : \mathsf{Type}_{u'} \) be a sort of variables of sort \( S : \alpha \to \Sigma \).
  An \emph{\( L \)-term on \( \alpha : S \) of sort \( A \)}, the type of which is denoted \( \operatorname{\mathsf{Term}}_{\alpha:S} A \), is either
  \begin{itemize}
    \item a variable, comprised solely of a name \( n : \alpha \) such that \( S(n) = A \), or
    \item an application of a function symbol, comprised of some \( n : \mathbb N \), a map \( B : \operatorname{\mathsf{Fin}}n \to \Sigma \), a function symbol \( f : \operatorname{\mathsf{Functions}}(n, B, A) \), and terms \( t : \prod_{i : \operatorname{\mathsf{Fin}}n} \operatorname{\mathsf{Term}}_{\alpha:S} B(i) \).
  \end{itemize}
\end{definition}

n32566.content:
\begin{definition}
  Let \( L \) be a \( \Sigma \)-language, and let \( \alpha : \mathsf{Type}_{u'} \) and \( S : \alpha \to \Sigma \).
  We define the type of \emph{\( L \)-bounded formulae on \( \alpha : S \)} with free variables indexed by \( \alpha \), and \( n \) additional free variables of sorts \( f : \operatorname{\mathsf{Fin}}n \to \Sigma \), denoted \( \mathsf{BForm}_{\alpha:S}^f \), by the following constructors.
  \begin{itemize}
    \item \( \operatorname{\mathsf{falsum}} : \mathsf{BForm}_{\alpha:S}^f \);
    \item \( \operatorname{\mathsf{equal}} : \prod_{A : \Sigma} \operatorname{\mathsf{Term}}_{\alpha \oplus \operatorname{\mathsf{Fin}}n : S \oplus f} A \to \operatorname{\mathsf{Term}}_{\alpha \oplus \operatorname{\mathsf{Fin}}n : S \oplus f} A \to \mathsf{BForm}_{\alpha:S}^f \);
    \item \( \operatorname{\mathsf{rel}} : \prod_{m : \mathbb N} \prod_{B : \operatorname{\mathsf{Fin}}m \to \Sigma} \prod_{R : \operatorname{\mathsf{Relations}}(m, B)} \left( \prod_{i : \operatorname{\mathsf{Fin}}m} \operatorname{\mathsf{Term}}_{\alpha \oplus \operatorname{\mathsf{Fin}}n : S \oplus f} B(i) \right) \to \mathsf{BForm}_{\alpha:S}^f \);
    \item \( \operatorname{\mathsf{imp}} : \mathsf{BForm}_{\alpha:S}^f \to \mathsf{BForm}_{\alpha:S}^f \to \mathsf{BForm}_{\alpha:S}^f \); and
    \item \( \operatorname{\mathsf{all}} : \prod_{A : \Sigma} \mathsf{BForm}_{\alpha:S}^{A :: f} \to \mathsf{BForm}_{\alpha:S}^f \),
  \end{itemize}
  where the syntax \( A :: f \) denotes the cons operation on maps from \( \operatorname{\mathsf{Fin}}n \).\footnote{This is implemented in mathlib as \texttt{Fin.cons}.}
  An \emph{\( L \)-formula on \( \alpha : S \)} with free variables indexed by \( \alpha \) is an inhabitant of \( \mathsf{BForm}_{\alpha:S}^{\#[]} \).\footnote{The expression \( \#[] \) is mathlib's syntax for the unique map \( \operatorname{\mathsf{Fin}}0 \to \Sigma \).}
  An \emph{\( L \)-sentence} is an \( L \)-formula with free variables indexed by \( \operatorname{\mathsf{Empty}} : f \), where \( f \) is the unique function \( \operatorname{\mathsf{Empty}} \to \Sigma \).
  An \emph{\( L \)-theory} is a set of \( L \)-sentences.
\end{definition}

n32567.content:
\begin{definition}
  Let \( L \) be a \( \Sigma \)-language.
  A \emph{1-\( L \)-formula} of sort \( A \) is an \( L \)-bounded formula on \( \operatorname{\mathsf{Empty}} \) with one additional free variable of sort \( f : \operatorname{\mathsf{Fin}}1 \to \Sigma \) given by \( f(x) = A \).
\end{definition}

n32568.content:
\begin{definition}
  Let \( L \) be a \( \Sigma \)-language.
  The \emph{witness symbols} for \( L \) is the language \( L_W \) consisting of a single constant of sort \( A \) for every 1-\( L \)-formula of sort \( A \).
\end{definition}

n32569.content:
\begin{proposition}
  Let \( M \) be a nonempty \( L \)-structure.
  Then \( M \) has an \( L_W \)-structure such that for each 1-\( L \)-formula \( \phi \) of sort \( A \), there is a constant symbol \( c : \operatorname{\mathsf{Functions}}(0, \#[], A) \) such that
  \[ \forall x : M_A,\, \phi(x) \to \phi(c) \]
\end{proposition}

n32570.content:
\begin{proof}
  We define the interpretation of the constant for \( \phi \) to be some \( x : M \) such that \( M \vDash \phi(x) \) if one exists, or an arbitrary \( y : M \) otherwise.\footnote{Use mathlib's \texttt{Classical.epsilon}.}
  This defines an \( L_W \)-structure for \( M \), and clearly \( M \) satisfies the required property.
\end{proof}

n32571.content:
\begin{definition}
  For each \( n : \mathbb N \), we define
  \[ L^{(0)} = L;\quad L^{(n+1)} = L^{(n)} \oplus (L^{(n)})_W \]
  This forms a directed diagram of languages, which has a colimit \( L^{(\omega)} \).
  There are natural morphisms \( L \to L^{(\omega)} \) and \( L^{(n)} \to L^{(\omega)} \) which are expansions on \( M \).
\end{definition}

n32572.content:
\begin{proposition}
  Let \( M \) be a nonempty \( L \)-structure.
  Then \( M \) has an \( L^{(\omega)} \)-structure such that for each 1-\( L^{(\omega)} \)-formula \( \phi \) of sort \( A \), there is a constant symbol \( c : \operatorname{\mathsf{Functions}}(0, \#[], A) \) such that
  \[ \forall x : M_A,\, \phi(x) \to \phi(c) \]
  Then, by the Tarski--Vaught test (which must be proven in the many-sorted case), the set \( N \subseteq M \) comprised of all of the interpretations of \( L^{(\omega)} \)-terms, is the domain of an \( L^{(\omega)} \)-elementary substructure of \( M \).
\end{proposition}

n32573.content:
\begin{definition}
  Let \( L \) be an \( \mathbb N \)-language.
  A \emph{type raising morphism} is a map of languages \( L \xrightarrow{\operatorname{\mathsf{succ}}} L \), where \( \operatorname{\mathsf{succ}} : \mathbb N \to \mathbb N \) is the successor function.
\end{definition}

n32574.content:
\begin{definition}
  \label{def:relation_props}
  Let \( R : \sigma \to \tau \to \mathsf{Prop}\).
  We define
  \begin{itemize}
    \item the \emph{image} of \( R \) to be the set \( \operatorname{\mathsf{im}}R = \{ y : \tau \mid \exists x : \sigma,\, x \mathrel{R} y \} \);
    \item the \emph{coimage} of \( R \) to be the set \( \operatorname{\mathsf{coim}}R = \{ x : \sigma \mid \exists y : \tau,\, x \mathrel{R} y \} \) (note that this is \emph{not} the same as the category-theoretic coimage of a morphism);
    \item the \emph{field} of \( R \) to be the set \( \operatorname{\mathsf{field}}R = \operatorname{\mathsf{coim}}R \cup \operatorname{\mathsf{im}}R \);
    \item the \emph{image of \( R \) on} \( s : \operatorname{\mathsf{Set}}\sigma \) to be the set \( \operatorname{\mathsf{im}}R|_s = \{ y : \tau \mid \exists x \in s,\, x \mathrel{R} y \} \);
    \item the \emph{coimage of \( R \) on} \( t : \operatorname{\mathsf{Set}}\tau \) to be the set \( \operatorname{\mathsf{coim}}R|_t = \{ x : \sigma \mid \exists y \in t,\, x \mathrel{R} y \} \);
    \item the \emph{converse} of \( R \) to be the relation \( R^{-1} : \tau \to \sigma \to \mathsf{Prop}\) such that \( y \mathrel{R^{-1}} x \) if and only if \( x \mathrel{R} y \);
    \item if \( S : \tau \to \upsilon \to \mathsf{Prop}\), the \emph{composition} \( S \circ R : \sigma \to \upsilon \to \mathsf{Prop}\) is the relation given by \( x \mathrel{(S\circ R)} z \) if and only if there is \( y : \tau \) such that \( x \mathrel{R} y \) and \( y \mathrel{S} z \);
    \item for a natural number \( n \), the \emph{\( n \)th power} of \( R : \tau \to \tau \to \mathsf{Prop}\) is defined by \( R^{n+1} = R \circ R^n \) and \( R^0 \) is the identity relation on \( \operatorname{\mathsf{coim}}R \);
    \item for an integer \( n \), the \emph{\( n \)th power} of \( R : \tau \to \tau \to \mathsf{Prop}\) is defined by \( R^{(n : \mathbb Z)} = R^n \) and \( R^{-(n : \mathbb Z)} = (R^n)^{-1} \) for \( n : \mathbb N \).\footnote{This may be implemented using \texttt{Int.negInduction} from mathlib.}
  \end{itemize}
  We say that \( R \) is
  \begin{itemize}
    \item \emph{injective}, if \( s_1 \mathrel{R} t, s_2 \mathrel{R} t \) imply \( s_1 = s_2 \);
    \item \emph{surjective}, if for every \( t : \tau \), there is some \( s : \sigma \) such that \( s \mathrel{R} t \);
    \item \emph{coinjective}, if \( s \mathrel{R} t_1, s \mathrel{R} t_2 \) imply \( t_1 = t_2 \);
    \item \emph{cosurjective}, if for every \( s : \sigma \), there is some \( t : \tau \) such that \( s \mathrel{R} t \);
    \item \emph{functional}, if \( R \) is coinjective and cosurjective, or equivalently, for every \( s : \sigma \) there is exactly one \( t : \tau \) such that \( s \mathrel{R} t \);
    \item \emph{cofunctional}, if \( R \) is injective and surjective, or equivalently, for every \( t : \tau \) there is exactly one \( s : \sigma \) such that \( s \mathrel{R} t \);
    \item \emph{one-to-one}, if \( R \) is injective and coinjective;
    \item \emph{bijective}, if \( R \) is functional and cofunctional;
    \item \emph{permutative}, if \( R : \tau \to \tau \to \mathsf{Prop}\) is one-to-one and has equal image and coimage.
  \end{itemize}
  We also define the \emph{graph} of a function \( f : \sigma \to \tau \) to be the functional relation \( R : \sigma \to \tau \to \mathsf{Prop}\) given by \( (x, y) \in R \) if and only if \( f(x) = y \).
  Most of these definitions are from \url{https://www.kylem.net/math/relations.html}, and most of these are in mathlib under \texttt{Mathlib.Logic.Relator}.
\end{definition}

n32575.content:
\begin{proposition}\mbox\negthinspace
  \uses{def:relation_props}
  \label{prop:relation_results}
  \begin{enumerate}
    \item \( R : \tau \to \tau \to \mathsf{Prop}\) is permutative if and only if it is one-to-one and for all \( x : \tau \), there exists \( y \) such that \( x \mathrel{R} y \) if and only if there exists \( y \) such that \( y \mathrel{R} x \).
    \item If \( R, S : \tau \to \tau \to \mathsf{Prop}\) are permutative and \( \operatorname{\mathsf{coim}}R \cap \operatorname{\mathsf{coim}}S = \emptyset \), then \( R \sqcup S \) is permutative and has coimage \( \operatorname{\mathsf{coim}}R \cup \operatorname{\mathsf{coim}}S \).
    \item If \( R, S : \tau \to \tau \to \mathsf{Prop}\) are permutative and \( \operatorname{\mathsf{coim}}R = \operatorname{\mathsf{coim}}S \), then \( R \circ S \) is permutative and has coimage equal to that of \( R \) and \( S \).
    \item If \( R \) is permutative, then \( \operatorname{\mathsf{coim}}R^n = \operatorname{\mathsf{coim}}R = \operatorname{\mathsf{im}}R = \operatorname{\mathsf{im}}R^n \) for any natural number or integer \( n \).
    \item If \( R \) is permutative and \( s_1, s_2 \subseteq \operatorname{\mathsf{coim}}R \), then the image of \( R \) on \( s_1 \) is equal to \( s_2 \) if and only if the coimage of \( R \) on \( s_2 \) is equal to \( s_1 \).
  \end{enumerate}
\end{proposition}

n32576.content:
\begin{definition}
  \label{def:OrbitRestriction}
  \lean{Rel.OrbitRestriction}
  \leanok
  Let \( s : \operatorname{\mathsf{Set}}\tau \).
  An \emph{orbit restriction} for \( s \) (over some type \( \sigma \)) consists of a set \( t : \operatorname{\mathsf{Set}}\tau \) disjoint from \( s \), a function \( f : \tau \to \sigma \), and a permutation \( \pi : \sigma \simeq \sigma \), such that for each \( u : \sigma \), the set \( t \cap f^{-1}(u) \) has cardinality at least \( \max(\aleph_0, \#s, \#d) \).

  An orbit restriction encapsulates information about how orbits should be completed.
  \begin{itemize}
    \item \( t \) is the \emph{sandbox}, the set inside which all added items must reside.
    \item \( f \) is a \emph{categorisation function}, placing each value \( x : \tau \) into a category \( u : \sigma \).
    \item \( \pi \) is a permutation of categories. If \( x \) has category \( u \), then anything that \( x \) is mapped to should have category \( \pi(u) \).
  \end{itemize}
\end{definition}

n32577.content:
\begin{proposition}[completing restricted orbits]
  \uses{def:OrbitRestriction}
  \label{prop:completing_restricted_orbits}
  \lean{Rel.permutativeExtension}
  \leanok
  Let \( R : \tau \to \tau \to \mathsf{Prop}\) be a one-to-one relation, and let \( (t, f, \pi) \) be an orbit restriction for \( \operatorname{\mathsf{field}}R \) over some type \( \sigma \).
  Then there is a permutative relation \( T \) such that
  \begin{itemize}
    \item \( \operatorname{\mathsf{coim}}T \subseteq \operatorname{\mathsf{field}}R \cup t \);
    \item \( \#\operatorname{\mathsf{coim}}T \leq \max(\aleph_0, \#\operatorname{\mathsf{coim}}R) \);
    \item \( R \leq T \); and
    \item if \( (x, y) \in T \), then \( (x, y) \in R \vee f(y) = \pi(f(x)) \).
  \end{itemize}
\end{proposition}

n32578.content:
\begin{proof}
  \leanok
  For each \( u : \sigma \), define an injection \( i_u : \operatorname{\mathsf{field}}R \times \mathbb N \to \tau \) where \( \operatorname{\mathsf{im}}i_u \subseteq t \cap f^{-1}(u) \).
  Define a relation \( S \) on \( \tau \) by the following constructors.
  \begin{align*}
    \forall x \in \operatorname{\mathsf{coim}}R \setminus \operatorname{\mathsf{im}}R,\, &(i_{\pi^{-1}(f(x))}(x, 0), x) \in S \\
    \forall n : \mathbb N,\, \forall x \in \operatorname{\mathsf{coim}}R \setminus \operatorname{\mathsf{im}}R,\, &(i_{\pi^{-n-2}(x)}(x, n+1), i_{\pi^{-n-1}(x)}(x, n)) \in S \\
    \forall x \in \operatorname{\mathsf{im}}R \setminus \operatorname{\mathsf{coim}}R,\, &(x, i_{\pi(f(x))}(x, 0)) \in S \\
    \forall n : \mathbb N,\, \forall x \in \operatorname{\mathsf{im}}R \setminus \operatorname{\mathsf{coim}}R,\, &(i_{\pi^{n+1}(f(x))}(x, n), i_{\pi^{n+2}(f(x))}(x, n+1)) \in S
  \end{align*}
  Note that \( (x, y) \in S \) implies \( f(y) = \pi(f(x)) \).
  Finally, as \( R \sqcup S \) is permutative, it satisfies the required conclusion.
\end{proof}

n32579.content:
\begin{proposition}[completing orbits]
  \label{prop:completing_orbits}
  \lean{Rel.permutativeExtension'}
  \leanok
  Let \( R : \tau \to \tau \to \mathsf{Prop}\) be a one-to-one relation.
  Let \( s : \operatorname{\mathsf{Set}}\tau \) be an infinite set such that \( \#\operatorname{\mathsf{field}}R \leq \#s \), and \( \operatorname{\mathsf{field}}R \) and \( s \) are disjoint.
  Then there is a permutative relation \( S \) such that \( R \leq S \) and \( \operatorname{\mathsf{coim}}S \subseteq \operatorname{\mathsf{field}}R \cup s \).
\end{proposition}

n32580.content:
\begin{proof}
  \leanok
  \uses{prop:completing_restricted_orbits}
  Define the orbit restriction \( (s, f, \pi) \) for \( \operatorname{\mathsf{field}}R \) over \( \mathsf{Unit}\).
  Note that for this to be defined, we used the inequality
  \[ \#s \geq \max(\aleph_0, \#\operatorname{\mathsf{field}}R) \]
  Use \cref{prop:completing_restricted_orbits} to obtain a permutative relation \( T \) extending \( R \) defined on \( \operatorname{\mathsf{field}}R \cup s \).
\end{proof}

n32581.content:
\begin{lemma}[mathlib]
  \label{prop:card_subset_card_lt_cof}
  Let \( \#\mu \) be a strong limit cardinal.
  Then there are precisely \( \#\mu \)-many subsets of \( \mu \) of size strictly less than \( \operatorname{\mathsf{cof}}(\operatorname{\mathsf{ord}}(\#\mu)) \).
\end{lemma}

n32582.content:
\begin{proof}
  Endow \( \mu \) with its initial well-ordering.
  Each such subset is bounded in \( \mu \) with respect to this well-ordering as its size is less than \( \operatorname{\mathsf{cof}}(\operatorname{\mathsf{ord}}(\#\mu)) \).
  So it suffices to prove there are precisely \( \#\mu \)-many bounded subsets of \( \mu \).
  \begin{align*}
    \#\{ s : \operatorname{\mathsf{Set}}\mu \mid \exists \nu : \mu,\, \forall x \in s,\, x < \nu \}
    &= \#\bigcup_{\nu : \mu} \{ s : \operatorname{\mathsf{Set}}\mu \mid \forall x \in s,\, x < \nu \} \\
    &\leq \sum_{\nu : \mu} \#\{ s : \operatorname{\mathsf{Set}}\mu \mid \forall x \in s,\, x < \nu \} \\
    &= \sum_{\nu : \mu} \#\{ s : \operatorname{\mathsf{Set}}\{ x : \mu \mid x < \nu \}\} \\
    &= \sum_{\nu : \mu} \underbrace{2^{\#\{ x : \mu \mid x < \nu \}}}_{<\mu} \\
    &\leq \mu
  \end{align*}
\end{proof}

